/**
 * `GeolocationButton` — bottom-right, opt-in (`controlslist="geolocation"`)
 * locate control. Ported from MapML.js's `src/mapml/control/GeolocationButton.js`
 * (a Leaflet `Control` wrapping the `leaflet.locatecontrol` plugin) to an
 * OpenLayers `ol/control/Control`.
 *
 * OpenLayers ships no locate control, so the plugin's behaviour is rebuilt on
 * `ol/Geolocation` (continuous `watchPosition` tracking + a projected accuracy
 * polygon). The control reproduces MapML.js's three localized surfaces:
 *
 *   1. The button title, cycling with the tracking state:
 *        - `btnLocTrackOff`       — OFF (not tracking)
 *        - `btnLocTrackOn`        — FOLLOWING (map recentres on each fix)
 *        - `btnLocTrackLastKnown` — BACKGROUND (tracking, user panned away)
 *   2. The user-location dot's `title` + `aria-label`, flipping between
 *        - `btnMyLocTrackOn`          — FOLLOWING
 *        - `btnMyLastKnownLocTrackOn` — BACKGROUND
 *   3. A permanent tooltip pinned to the dot in the FOLLOWING state (the OL
 *      analog of Leaflet's `bindTooltip(text, { permanent: true })`).
 *
 * The dot, its permanent tooltip and the translucent accuracy circle are drawn
 * with two `ol/Overlay`s (dot + tooltip) and one `ol/layer/Vector` (accuracy
 * polygon from `Geolocation.getAccuracyGeometry()`). Each fix dispatches
 * `maplocationfound` on the viewer (mirroring Leaflet's watched `locationfound`
 * re-dispatch); a geolocation error dispatches `locationerror`.
 */
import Control from 'ol/control/Control.js';
import Geolocation from 'ol/Geolocation.js';
import Overlay from 'ol/Overlay.js';
import VectorLayer from 'ol/layer/Vector.js';
import VectorSource from 'ol/source/Vector.js';
import Feature from 'ol/Feature.js';
import { Style, Fill, Stroke } from 'ol/style.js';
import { transform } from 'ol/proj.js';

// FontAwesome `location-arrow` / Material `near_me` paper-airplane arrow — the
// same silhouette MapML.js (via leaflet.locatecontrol) and MapML-MapLibre use.
// Embedded with `fill="currentColor"` so the button `color` (set per tracking
// state in CSS: black / orange / blue) tints it, exactly as MapML.js does.
const LOCATE_ICON =
  '<svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" height="22" width="22" viewBox="0 0 24 24" fill="currentColor">' +
  '<path d="M21 3L3 10.53v.98l6.84 2.65L12.48 21h.98L21 3z"/>' +
  '</svg>';

const STATE = {
  OFF: 'off',
  FOLLOWING: 'following',
  BACKGROUND: 'background'
};

const LOCATE_MAX_ZOOM = 16;

export class GeolocationButton extends Control {
  constructor(viewer) {
    const container = document.createElement('div');
    container.className = 'mapml-geolocation-button ol-control';

    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'mapml-button';
    button.innerHTML = LOCATE_ICON;
    container.appendChild(button);

    super({ element: container });

    this._viewer = viewer;
    this._button = button;
    this._state = STATE.OFF;

    this._onClick = (event) => {
      event.stopPropagation();
      this._toggle();
    };
    this._onPosition = () => this._handlePosition();
    this._onError = (error) => this._handleError(error);
    // A real pointer drag (never our own programmatic recentre) drops FOLLOWING
    // to BACKGROUND — the OL analog of leaflet.locatecontrol's stop-on-drag.
    this._onPointerDrag = () => {
      if (this._state === STATE.FOLLOWING) {
        this._setState(STATE.BACKGROUND);
      }
    };

    button.addEventListener('click', this._onClick);
    this._updateTitle();
  }

  destroy() {
    this.stop();
    this._button.removeEventListener('click', this._onClick);
  }

  // --- state machine -----------------------------------------------------

  _toggle() {
    if (this._state === STATE.OFF) {
      this._start();
    } else if (this._state === STATE.BACKGROUND) {
      this._resumeFollowing();
    } else {
      this.stop();
    }
  }

  _start() {
    const map = this.getMap();
    if (!map) return;
    this._firstFix = true;
    this._geolocation = new Geolocation({
      tracking: true,
      projection: map.getView().getProjection(),
      trackingOptions: {
        enableHighAccuracy: true,
        maximumAge: 0,
        timeout: 60000
      }
    });
    this._geolocation.on('change:position', this._onPosition);
    this._geolocation.on('error', this._onError);
    map.on('pointerdrag', this._onPointerDrag);
    this._setState(STATE.FOLLOWING);
  }

  // Public: stop tracking and tear the marker down (called by the viewer's
  // locate() API and on destroy — matches MapML.js `GeolocationButton.stop`).
  stop() {
    if (this._state === STATE.OFF) return;
    const map = this.getMap();
    if (this._geolocation) {
      this._geolocation.setTracking(false);
      this._geolocation.un('change:position', this._onPosition);
      this._geolocation.un('error', this._onError);
      this._geolocation = null;
    }
    if (map) {
      map.un('pointerdrag', this._onPointerDrag);
    }
    this._removeMarker();
    this._setState(STATE.OFF);
  }

  _resumeFollowing() {
    this._setState(STATE.FOLLOWING);
    const map = this.getMap();
    if (map && this._lastPosition) {
      map.getView().setCenter(this._lastPosition);
    }
  }

  _setState(state) {
    this._state = state;
    this._updateTitle();
    this._updateMarkerLabels();
  }

  // --- geolocation callbacks --------------------------------------------

  _handlePosition() {
    const map = this.getMap();
    const position = this._geolocation?.getPosition();
    if (!map || !position) return;
    this._lastPosition = position;
    const accuracyGeometry = this._geolocation.getAccuracyGeometry();
    this._renderMarker(position, accuracyGeometry);

    if (this._state === STATE.FOLLOWING) {
      const view = map.getView();
      if (this._firstFix && accuracyGeometry) {
        // Fit the accuracy circle, capped at LOCATE_MAX_ZOOM — the OL analog of
        // Leaflet locate()'s setView(bounds, maxZoom).
        view.fit(accuracyGeometry.getExtent(), { maxZoom: LOCATE_MAX_ZOOM });
      } else {
        view.setCenter(position);
      }
    }
    this._firstFix = false;

    // Dispatch maplocationfound with EPSG:4326 lat/lng (like Leaflet's event).
    const [lon, lat] = transform(
      position,
      map.getView().getProjection(),
      'EPSG:4326'
    );
    this._viewer._fireLocationFound({
      latitude: lat,
      longitude: lon,
      accuracy: this._geolocation.getAccuracy()
    });
  }

  _handleError(error) {
    this._viewer._fireLocationError(error?.message || 'Geolocation error.');
    this.stop();
  }

  // --- marker (dot + tooltip + accuracy circle) --------------------------

  _createMarkerLayers() {
    const map = this.getMap();
    if (!map) return;

    this._accuracyFeature = new Feature();
    this._accuracyLayer = new VectorLayer({
      source: new VectorSource({ features: [this._accuracyFeature] }),
      style: new Style({
        fill: new Fill({ color: 'rgba(45, 140, 255, 0.15)' }),
        stroke: new Stroke({ color: 'rgba(45, 140, 255, 0.4)', width: 1 })
      }),
      zIndex: 1000
    });
    map.addLayer(this._accuracyLayer);

    this._dotEl = document.createElement('div');
    this._dotEl.className = 'mapml-location-dot';
    this._dotEl.setAttribute('role', 'img');
    this._dotEl.setAttribute('tabindex', '0');
    this._dotOverlay = new Overlay({
      element: this._dotEl,
      positioning: 'center-center',
      stopEvent: false
    });
    map.addOverlay(this._dotOverlay);

    this._tipEl = document.createElement('div');
    this._tipEl.className = 'mapml-location-tooltip';
    this._tooltipOverlay = new Overlay({
      element: this._tipEl,
      positioning: 'bottom-center',
      offset: [0, -14],
      stopEvent: false
    });
    map.addOverlay(this._tooltipOverlay);
  }

  _renderMarker(position, accuracyGeometry) {
    if (!this._accuracyLayer) this._createMarkerLayers();
    if (accuracyGeometry) {
      this._accuracyFeature.setGeometry(accuracyGeometry);
    }
    this._dotOverlay.setPosition(position);
    this._tooltipOverlay.setPosition(position);
    this._updateMarkerLabels();
  }

  _removeMarker() {
    const map = this.getMap();
    if (map) {
      if (this._accuracyLayer) map.removeLayer(this._accuracyLayer);
      if (this._dotOverlay) map.removeOverlay(this._dotOverlay);
      if (this._tooltipOverlay) map.removeOverlay(this._tooltipOverlay);
    }
    this._accuracyLayer = null;
    this._accuracyFeature = null;
    this._dotOverlay = null;
    this._dotEl = null;
    this._tooltipOverlay = null;
    this._tipEl = null;
  }

  // --- labels / title ----------------------------------------------------

  _updateMarkerLabels() {
    if (!this._dotEl) return;
    const locale = this._viewer.locale;
    if (this._state === STATE.FOLLOWING) {
      this._dotEl.title = locale.btnMyLocTrackOn;
      this._dotEl.setAttribute('aria-label', locale.btnMyLocTrackOn);
      this._tipEl.textContent = locale.btnMyLocTrackOn;
      this._tipEl.hidden = false;
    } else {
      this._dotEl.title = locale.btnMyLastKnownLocTrackOn;
      this._dotEl.setAttribute('aria-label', locale.btnMyLastKnownLocTrackOn);
      this._tipEl.hidden = true;
    }
  }

  _updateTitle() {
    const locale = this._viewer.locale;
    let title;
    if (this._state === STATE.FOLLOWING) {
      title = locale.btnLocTrackOn;
    } else if (this._state === STATE.BACKGROUND) {
      title = locale.btnLocTrackLastKnown;
    } else {
      title = locale.btnLocTrackOff;
    }
    this._button.title = title;
    this._button.setAttribute('aria-label', title);
    // State-tinted icon (leaflet.locatecontrol parity): OFF = black (base),
    // FOLLOWING = orange, BACKGROUND (last-known) = blue.
    this._button.classList.toggle(
      'mapml-geolocation-following',
      this._state === STATE.FOLLOWING
    );
    this._button.classList.toggle(
      'mapml-geolocation-background',
      this._state === STATE.BACKGROUND
    );
  }
}
