/**
 * `DebugOverlay` — the OpenLayers port of MapML.js's
 * `src/mapml/layers/DebugOverlay.js`, the developer "debug mode" toggled by the
 * context menu (`D`) / `viewer.toggleDebug()`. It layers three diagnostics over
 * the map:
 *
 *   1. a **coordinate panel** — an HTML `<table class="mapml-debug">` pinned to
 *      the map's lower-left that spells out the pointer position in every MapML
 *      coordinate system (tile / tilematrix / map / tcrs / pcrs / gcrs), updated
 *      on `pointermove`. Only shown when the map is large enough (mirrors
 *      MapML.js's `mapSize.x > 400 || mapSize.y > 300` gate);
 *   2. a **tile grid** — an `ol/source/TileDebug` layer drawing each tile's
 *      `col`/`row`/`zoom` in red (the OL analog of MapML.js's `DebugGrid`);
 *   3. **bounds vectors** — an `ol/layer/Vector` with the projection centre and
 *      one rectangle per checked layer's PCRS bounds plus the aggregate
 *      (total) bounds (the analog of MapML.js's `DebugVectors`).
 *
 * MapML.js is Leaflet (SVG paths + DOM panes); OpenLayers renders features to a
 * canvas, so the grid and bounds have no per-feature DOM. This follows the same
 * canvas re-architecture the feature/style ports use — assert against the
 * `ol/source/Vector` features (tagged with `debugClass`), not CSS selectors.
 */
import TileLayer from 'ol/layer/Tile.js';
import TileDebug from 'ol/source/TileDebug.js';
import VectorLayer from 'ol/layer/Vector.js';
import VectorSource from 'ol/source/Vector.js';
import Feature from 'ol/Feature.js';
import Polygon from 'ol/geom/Polygon.js';
import Circle from 'ol/geom/Circle.js';
import Style from 'ol/style/Style.js';
import Stroke from 'ol/style/Stroke.js';
import Fill from 'ol/style/Fill.js';
import { transform } from 'ol/proj.js';
import { createCanvasContext2D } from 'ol/dom.js';
import { getProjection, getTileGrid } from '../geo/crs/olcrs.js';
import { Util } from '../utils/Util.js';
import { toPoint as point } from '../geometry/Point.js';
import { toBounds as bounds } from '../geometry/Bounds.js';

// Per-layer bounds rectangle colours, cycled in order (ported from MapML.js
// DebugVectors `colors`).
const BOUNDS_COLORS = ['#FF5733', '#8DFF33', '#3397FF', '#E433FF', '#F3FF33'];

export class DebugOverlay {
  constructor(viewer) {
    this._viewer = viewer;
    this._map = viewer.map;
    this._onPointerMove = this._updateCoords.bind(this);
    this._onLayersChange = () => this._rebuildVectors();
    this._onAddLayer = (e) => {
      if (e.element === this._grid || e.element === this._vectors) return;
      e.element.on('change:visible', this._onLayersChange);
      this._rebuildVectors();
    };
    this._onRemoveLayer = (e) => {
      if (e.element === this._grid || e.element === this._vectors) return;
      e.element.un('change:visible', this._onLayersChange);
      this._rebuildVectors();
    };
  }

  // Ported from MapML.js DebugOverlay.onAdd.
  enable() {
    if (this._enabled) return this;
    this._enabled = true;

    const size = this._map.getSize() ?? [0, 0];
    // Only show the coordinate panel when the map has room for it.
    if (size[0] > 400 || size[1] > 300) {
      this._createPanel();
      this._map.on('pointermove', this._onPointerMove);
    }

    const mProj = window.M[this._viewer.projection];
    const gridSource = new TileDebug({
      projection: getProjection(mProj),
      tileGrid: getTileGrid(mProj)
    });
    // TileDebug's built-in loader hardcodes a 24px centred label that spills
    // into neighbouring tiles; replace it with a smaller label pinned to each
    // tile's top-left corner (echoing MapML.js's `.mapml-debug-tile`
    // `text-indent`/top-left placement + dashed-red outline).
    gridSource.setLoader((z, x, y) => {
      const [width, height] = gridSource.getTileSize(z);
      const context = createCanvasContext2D(width, height);
      const pad = 4;
      context.strokeStyle = 'red';
      context.setLineDash([4, 4]);
      context.strokeRect(0.5, 0.5, width - 1, height - 1);
      context.setLineDash([]);
      context.font = '11px sans-serif';
      context.textAlign = 'left';
      context.textBaseline = 'top';
      const text = `col: ${x}, row: ${y}, zoom: ${z}`;
      context.strokeStyle = 'white';
      context.lineWidth = 3;
      context.strokeText(text, pad, pad, width - pad * 2);
      context.fillStyle = 'red';
      context.fillText(text, pad, pad, width - pad * 2);
      return Promise.resolve(context.canvas);
    });
    this._grid = new TileLayer({ source: gridSource });
    this._grid.set('mapmlDebug', 'grid');
    this._grid.setZIndex(400);
    this._map.addLayer(this._grid);

    this._vectors = new VectorLayer({ source: new VectorSource() });
    this._vectors.set('mapmlDebug', 'vectors');
    this._vectors.setZIndex(401);
    this._map.addLayer(this._vectors);

    // Bind layer add/remove/visibility listeners so the bounds rectangles track
    // layers being (de)selected in the layer control (the OL analog of
    // MapML.js's overlayadd/overlayremove handlers).
    const layers = this._map.getLayers();
    layers.on('add', this._onAddLayer);
    layers.on('remove', this._onRemoveLayer);
    layers.forEach((l) => {
      if (l !== this._grid && l !== this._vectors) {
        l.on('change:visible', this._onLayersChange);
      }
    });

    // Defer so freshly (re)checked layers have finished computing their bounds,
    // mirroring MapML.js's `setTimeout(..., 0)` in DebugVectors._addBounds.
    this._rebuildVectors();
    return this;
  }

  // Ported from MapML.js DebugOverlay.onRemove.
  disable() {
    if (!this._enabled) return this;
    this._enabled = false;

    this._map.un('pointermove', this._onPointerMove);
    const layers = this._map.getLayers();
    layers.un('add', this._onAddLayer);
    layers.un('remove', this._onRemoveLayer);
    layers.forEach((l) => l.un('change:visible', this._onLayersChange));

    if (this._grid) {
      this._map.removeLayer(this._grid);
      this._grid = null;
    }
    if (this._vectors) {
      this._map.removeLayer(this._vectors);
      this._vectors = null;
    }
    this._container?.remove();
    this._container = null;
    return this;
  }

  // ---- Coordinate panel ---------------------------------------------------
  // Ported from MapML.js DebugPanel.onAdd: a <table> with a banner caption and
  // one <tr> per coordinate system, in the same order MapML.js creates them.
  _createPanel() {
    const table = document.createElement('table');
    table.className = 'mapml-debug';

    const caption = document.createElement('caption');
    caption.className = 'mapml-debug-banner';
    caption.textContent = 'Debug mode';
    table.appendChild(caption);

    const tbody = document.createElement('tbody');
    tbody.className = 'mapml-debug-panel';
    this._rows = {};
    for (const key of ['tile', 'tilematrix', 'map', 'tcrs', 'pcrs', 'gcrs']) {
      const tr = document.createElement('tr');
      tr.className = 'mapml-debug-coordinates';
      tbody.appendChild(tr);
      this._rows[key] = tr;
    }
    table.appendChild(tbody);

    this._viewer._container.appendChild(table);
    this._container = table;
  }

  // Ported from MapML.js DebugPanel._updateCoords.
  _updateCoords(evt) {
    // Freeze the read-out while the context menu is open (MapML.js checks
    // `this.contextMenu._visible`).
    if (this._viewer._contextMenu && !this._viewer._contextMenu._menu.hidden) {
      return;
    }
    if (!this._rows) return;
    const crs = window.M[this._viewer.projection];
    const projection = getProjection(crs);
    const view = this._map.getView();
    const zoom = Math.round(view.getZoom());
    const coordinate = evt.coordinate;
    const pixel = evt.pixel;
    // OpenLayers' projected view coordinate IS the PCRS; forward-transform it to
    // TCRS (pixel) at the current zoom, the way MapML.js reads `map.project`.
    const tcrs = crs.transformation.transform(
      point(coordinate[0], coordinate[1]),
      crs.scale(zoom)
    );
    const tileSize = crs.options.crs.tile.bounds.max.x;
    let pointI = tcrs.x % tileSize;
    let pointJ = tcrs.y % tileSize;
    if (pointI < 0) pointI += tileSize;
    if (pointJ < 0) pointJ += tileSize;
    const gcrs = transform(coordinate, projection.getCode(), 'EPSG:4326');

    this._rows.tile.innerHTML = `
      <th scope="row">tile: </th>
      <td>i: ${Math.trunc(pointI)}, </td>
      <td>j: ${Math.trunc(pointJ)}</td>
      `;
    this._rows.tilematrix.innerHTML = `
      <th scope="row">tilematrix: </th>
      <td>column: ${Math.trunc(tcrs.x / tileSize)}, </td>
      <td>row: ${Math.trunc(tcrs.y / tileSize)}</td>
      `;
    this._rows.map.innerHTML = `
      <th scope="row">map: </th>
      <td>i: ${Math.trunc(pixel[0])}, </td>
      <td>j: ${Math.trunc(pixel[1])}</td>
      `;
    this._rows.tcrs.innerHTML = `
      <th scope="row">tcrs: </th>
      <td>x: ${Math.trunc(tcrs.x)}, </td>
      <td>y: ${Math.trunc(tcrs.y)}</td>
      `;
    this._rows.pcrs.innerHTML = `
      <th scope="row">pcrs: </th>
      <td>easting: ${coordinate[0].toFixed(2)}, </td>
      <td>northing: ${coordinate[1].toFixed(2)}</td>
      `;
    this._rows.gcrs.innerHTML = `
      <th scope="row">gcrs: </th>
      <td>lon: ${gcrs[0].toFixed(6)}, </td>
      <td>lat: ${gcrs[1].toFixed(6)}</td>
      `;
  }

  // ---- Bounds vectors -----------------------------------------------------
  // Ported from MapML.js DebugVectors (onAdd + _addBounds): projection centre,
  // one rectangle per checked layer's PCRS bounds, and the aggregate bounds.
  _rebuildVectors() {
    if (!this._vectors) return;
    const source = this._vectors.getSource();
    source.clear();

    // Projection centre — a circle at PCRS (0, 0). In OpenLayers the view
    // projection IS the PCRS, so no Leaflet-style round-trip is needed.
    const centre = new Feature({ geometry: new Circle([0, 0], 250) });
    centre.set('debugClass', 'projection-centre');
    centre.set('title', 'Projection Center');
    centre.setStyle(
      new Style({
        stroke: new Stroke({ color: '#3388ff', width: 3 }),
        fill: new Fill({ color: 'rgba(51, 136, 255, 0.2)' })
      })
    );
    source.addFeature(centre);

    let total;
    let i = 0;
    for (const layerEl of this._viewer.layers) {
      if (!layerEl.checked) continue;
      // `layerEl.extent` runs _calculateBounds() (a bare `layerEl.bounds` read
      // does not); convert the resulting envelope to a PCRS Bounds the way
      // AnnounceMovement does.
      const extent = layerEl.extent;
      const b = extent ? Util.extentToBounds(extent, 'pcrs') : null;
      if (!b) continue;
      const rect = this._boundsFeature(b);
      const color = BOUNDS_COLORS[i % BOUNDS_COLORS.length];
      // Tag with the layer's data-testid (MapML.js's `boundsTestTag`) so the
      // rectangle is identifiable in tests / when debugging.
      const testid = layerEl.getAttribute('data-testid');
      rect.set('debugClass', testid || 'layer-bounds');
      rect.set('title', layerEl.label || '');
      rect.setStyle(
        new Style({
          stroke: new Stroke({ color, width: 2 }),
          fill: new Fill({ color: 'rgba(0, 0, 0, 0.01)' })
        })
      );
      source.addFeature(rect);
      i++;
      total = total ? total.extend(b) : bounds(b.min, b.max);
    }

    if (total) {
      const totalRect = this._boundsFeature(total);
      totalRect.set('debugClass', 'mapml-total-bounds');
      totalRect.setStyle(
        new Style({
          stroke: new Stroke({ color: '#808080', width: 5 })
        })
      );
      source.addFeature(totalRect);
    }
  }

  // A rectangle ol/Feature from a PCRS Bounds (min/max Points). PCRS coords drop
  // straight onto the view-projection source.
  _boundsFeature(b) {
    const { min, max } = b;
    return new Feature({
      geometry: new Polygon([
        [
          [min.x, min.y],
          [max.x, min.y],
          [max.x, max.y],
          [min.x, max.y],
          [min.x, min.y]
        ]
      ])
    });
  }
}

// Factory mirroring MapML.js's `debugOverlay()`.
export function debugOverlay(viewer) {
  return new DebugOverlay(viewer);
}
