/**
 * `AnnounceMovement` — the OpenLayers port of MapML.js's
 * `src/mapml/handlers/AnnounceMovement.js`, the screen-reader live-region that
 * spells out zoom / pan / bounds events. Opt-in via `M.options.announceMovement`
 * (set through a `<map-options>` element), mirroring MapML.js.
 *
 * MapML.js implements this as a Leaflet `Handler` bound to the map; OpenLayers
 * has no such abstraction, so this is a plain enable/disable class (matching the
 * other ported handlers). It mounts a visually-hidden `<output>` in the viewer
 * shadow root and, on every user `moveend`, either announces the current zoom
 * (`"zoom level N"`, prefixed with the min/max-zoom message at the boundaries)
 * or — when the new view leaves the aggregate layer bounds — bounces the map
 * back to the previous history entry and announces the direction
 * (`amWestBound` / `amEastBound` / `amNorthBound` / `amSouthBound` /
 * `amZoomedOut` / `amDraggedOut`).
 *
 * The `moveend` listener is registered AFTER `MapHistory.enable()` so the
 * history array is already updated for the current move when this runs (the OL
 * analog of MapML.js running `_addToHistory()` before dispatching the
 * `map-moveend` event that drives `announceBounds`).
 */
import { Util } from '../utils/Util.js';
import { toBounds as bounds } from '../geometry/Bounds.js';

export class AnnounceMovement {
  constructor(viewer) {
    this._viewer = viewer;
    this._map = viewer.map;
    this._output = null;
    // Set by a `pointerdrag` (the OL analog of Leaflet's draggable `dragstart`)
    // so an out-of-bounds move made by dragging announces `amDraggedOut`.
    this._wasDragged = false;
    this._onMoveEnd = this._announceBounds.bind(this);
    this._onPointerDrag = () => {
      this._wasDragged = true;
    };
    this._onFocus = this._focusAnnouncement.bind(this);
  }

  enable() {
    if (this._enabled) {
      return this;
    }
    this._enabled = true;
    // Visually-hidden live region. Inserted as the shadow root's first child so
    // `shadowRoot.querySelector('output')` returns this one (ahead of the
    // feature-index overlay's own `<output>`, which lives in the map viewport),
    // matching MapML.js's test selector shape.
    const output = document.createElement('output');
    output.className = 'mapml-screen-reader-output';
    output.setAttribute('role', 'status');
    output.setAttribute('aria-live', 'polite');
    output.setAttribute('aria-atomic', 'true');
    const shadow = this._viewer.shadowRoot;
    shadow.insertBefore(output, shadow.firstChild);
    this._output = output;

    this._map.on('moveend', this._onMoveEnd);
    this._map.on('pointerdrag', this._onPointerDrag);
    this._viewer.addEventListener('focus', this._onFocus);
    return this;
  }

  disable() {
    if (!this._enabled) {
      return this;
    }
    this._enabled = false;
    this._map.un('moveend', this._onMoveEnd);
    this._map.un('pointerdrag', this._onPointerDrag);
    this._viewer.removeEventListener('focus', this._onFocus);
    this._output?.remove();
    this._output = null;
    return this;
  }

  // Aggregate PCRS bounds of every `<map-layer>` with a computable extent.
  // Ported from MapML.js's `AnnounceMovement.totalBounds`, but computed on
  // demand (the OL analog of `this._map.totalLayerBounds`).
  _totalLayerBounds() {
    let bnds;
    for (const layerEl of this._viewer.layers) {
      const extent = layerEl.extent;
      if (!extent) {
        continue;
      }
      const b = Util.extentToBounds(extent, 'pcrs');
      if (!b) {
        continue;
      }
      if (bnds) {
        bnds.extend(b);
      } else {
        bnds = bounds(b.min, b.max);
      }
    }
    return bnds;
  }

  // Ported from MapML.js's `AnnounceMovement.announceBounds`.
  _announceBounds() {
    const output = this._output;
    const history = this._viewer._history;
    if (!output || !history) {
      return;
    }
    const view = this._map.getView();
    const locale = this._viewer.locale;
    // OpenLayers' resolution constraint can leave a fractional zoom (e.g. it
    // clamps zoom-out to the level that fills the viewport); the keyboard zoom
    // is whole-level like Leaflet's, so round for the level the user perceives
    // (MapML.js announces integer `getZoom()`).
    const mapZoom = Math.round(view.getZoom());

    // OpenLayers' projected view extent IS the PCRS (unlike Leaflet, which
    // needs `pixelToPCRSBounds` from the pixel bounds), so read it directly.
    const size = this._map.getSize();
    const viewExtent = size ? view.calculateExtent(size) : null;
    const mapBounds = viewExtent
      ? bounds(
          [viewExtent[0], viewExtent[1]],
          [viewExtent[2], viewExtent[3]]
        )
      : null;

    // MapML.js compares against `getMaxZoom()` (the projection's zoom count) and
    // `_layersMinZoom` (min zoom across active layers). The OL viewer doesn't
    // track a per-layer min, so the view's own min/max are the closest analog.
    const minZoom = view.getMinZoom();
    const maxZoom = view.getMaxZoom();

    const totalLayerBounds = this._totalLayerBounds();
    let visible = true;
    if (totalLayerBounds && mapBounds) {
      visible =
        mapZoom <= maxZoom &&
        mapZoom >= minZoom &&
        totalLayerBounds.overlaps(mapBounds);
    }

    const standard = locale.amZoom + ' ' + mapZoom;

    if (!visible) {
      const h = history._history;
      const i = history._historyIndex;
      const outOfBoundsPos = h[i];
      const inBoundsPos = h[i - 1];
      // No in-bounds entry to fall back to (fresh view): just announce zoom.
      if (!outOfBoundsPos || !inBoundsPos) {
        output.textContent = standard;
        this._wasDragged = false;
        return;
      }
      // Bounce back to the last in-bounds view and trim the out-of-bounds tail
      // so forward() can't return to it. MapHistory.back() sets its traversal
      // guard so the replay's `moveend` isn't re-recorded; that same replay
      // re-runs this handler in-bounds, re-announcing the restored zoom.
      this._viewer.back();
      history._history.pop();
      if (Math.round(outOfBoundsPos.zoom) !== Math.round(inBoundsPos.zoom)) {
        output.textContent = locale.amZoomedOut;
      } else if (this._wasDragged) {
        output.textContent = locale.amDraggedOut;
      } else if (outOfBoundsPos.center[0] > inBoundsPos.center[0]) {
        output.textContent = locale.amEastBound;
      } else if (outOfBoundsPos.center[0] < inBoundsPos.center[0]) {
        output.textContent = locale.amWestBound;
      } else if (outOfBoundsPos.center[1] > inBoundsPos.center[1]) {
        // PCRS y increases northward (unlike Leaflet's pixel bounds, whose y
        // increases southward), so the north/south comparisons are flipped.
        output.textContent = locale.amNorthBound;
      } else if (outOfBoundsPos.center[1] < inBoundsPos.center[1]) {
        output.textContent = locale.amSouthBound;
      }
    } else {
      const prev = history._history[history._historyIndex - 1];
      const prevZoom = prev
        ? Math.round(prev.zoom)
        : Math.round(history._history[history._historyIndex]?.zoom);
      if (mapZoom === maxZoom && mapZoom !== prevZoom) {
        output.textContent = locale.amMaxZoom + ' ' + standard;
      } else if (mapZoom === minZoom && mapZoom !== prevZoom) {
        output.textContent = locale.amMinZoom + ' ' + standard;
      } else {
        output.textContent = standard;
      }
    }
    this._wasDragged = false;
  }

  // Ported from MapML.js's `AnnounceMovement.focusAnnouncement`: when the map
  // gains focus, temporarily set `aria-roledescription` on the map container so
  // a screen reader reads the current zoom (with min/max prefix) as the region
  // is entered, then clear it. MapML.js keys off a `mapfocused` event; the OL
  // viewer rests focus on the host itself on first Tab, so a `focus` listener on
  // the host is the analog.
  _focusAnnouncement() {
    const viewer = this._viewer;
    const locale = viewer.locale;
    const el = viewer._container;
    if (!el) {
      return;
    }
    setTimeout(() => {
      const view = this._map.getView();
      const mapZoom = view.getZoom();
      let standard = locale.amZoom + ' ' + mapZoom;
      if (mapZoom === view.getMaxZoom()) {
        standard = locale.amMaxZoom + ' ' + standard;
      } else if (mapZoom === view.getMinZoom()) {
        standard = locale.amMinZoom + ' ' + standard;
      }
      el.setAttribute('aria-roledescription', 'region ' + standard);
      setTimeout(() => {
        el.removeAttribute('aria-roledescription');
      }, 2000);
    }, 0);
  }
}
