/**
 * Stylesheet for the {@link FullscreenButton} top-left control. Sized 40×40
 * and stacked below the zoom bar (80px) and reload button (40px), each with an
 * 8px gap. The enter/exit artwork is MapML.js's fullscreen sprite (verbatim
 * from `MapML.js/src/mapml.css` `.leaflet-control-fullscreen a`), scaled for a
 * 40×40 button as in MapML-MapLibre's `iconOverrides.css`: a 34×68 sprite,
 * positioned `3px 3px` (enter) and `3px -31px` (exit). The exit frame is shown
 * by the `.is-fullscreen` class the control toggles on `fullscreenchange`.
 */

// MapML.js's 26×52 fullscreen sprite (enter rows 0..25, exit rows 26..51).
const FULLSCREEN_SPRITE_URL =
  "url(\"data:image/svg+xml,%0A%3Csvg width='26' height='52' xmlns='http://www.w3.org/2000/svg' xmlns:xlink='http://www.w3.org/1999/xlink'%3E%3Cg transform='translate(0 -1000.4)'%3E%3Cuse transform='translate(0 26)' width='100%25' height='100%25' xlink:href='%23a'/%3E%3Cuse transform='translate(0 26)' width='100%25' height='100%25' xlink:href='%23b'/%3E%3Cuse transform='translate(0 26)' width='100%25' height='100%25' xlink:href='%23c'/%3E%3Cuse transform='translate(0 26)' width='100%25' height='100%25' xlink:href='%23d'/%3E%3Cpath id='a' transform='translate(0 1000.4)' d='M5 15v6h6v-2H7v-4z' color='%23000' fill='%23000'/%3E%3Cpath id='b' transform='translate(0 1000.4)' d='M21 15v6h-6v-2h4v-4z' color='%23000' fill='%23000'/%3E%3Cpath d='M10 1037.4v4l1 1h4l1-1v-4l-1-1h-4z' color='%23000' fill='%23000'/%3E%3Cpath id='d' d='M5 1011.4v-6h6v2H7v4z' color='%23000' fill='%23000'/%3E%3Cpath id='c' d='M21 1011.4v-6h-6v2h4v4z' color='%23000' fill='%23000'/%3E%3C/g%3E%3C/svg%3E\")";

export const fullscreenButtonCss = /* css */ `
.mapml-fullscreen-button {
  left: .5em;
  padding: 0;
  background-color: #fff;
  border: 1px solid #e3e3e3;
  border-radius: 4px;
  box-shadow: rgb(0 0 0 / 30%) 0px 1px 4px -1px;
}

.mapml-fullscreen-button button.mapml-button {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  margin: 0;
  padding: 0;
  background-color: #fff;
  border: none;
  border-radius: 4px;
  cursor: pointer;
}

.mapml-fullscreen-button .mapml-fullscreen-button-icon {
  width: 100%;
  height: 100%;
  background-image: ${FULLSCREEN_SPRITE_URL};
  background-repeat: no-repeat;
  background-size: 34px 68px;
  background-position: 3px 3px;
}

.mapml-fullscreen-button button.is-fullscreen .mapml-fullscreen-button-icon {
  background-position: 3px -31px;
}

/* Drop ol.css's gray hover/focus outline and draw the shared focus ring. */
.mapml-fullscreen-button > button:hover,
.mapml-fullscreen-button > button:focus:not(:focus-visible) {
  outline: none;
}
.mapml-fullscreen-button > button:focus-visible {
  outline: 2px solid var(--mapml-focus-ring-color);
  outline-offset: 1px;
}
`;
