/**
 * `<map-tile>` — a single pre-addressed raster tile (`row`/`col`/`zoom`/`src`).
 * Ported from MapML.js `src/map-tile.js` (`HTMLTileElement`): the custom-element
 * surface (immutable-after-connect `row`/`col`/`zoom`, mutable `src`,
 * `position`/`extent` getters, shadow-crossing parent resolution).
 *
 * Rendering is re-architected onto OpenLayers: a run of adjacent `<map-tile>`s
 * contributes to one `MapTileLayer` (an `ol/layer/Tile`), looked up/created via
 * the owning element's position-keyed `_layerRegistry` so it interleaves with
 * `<map-feature>` runs (each a `MapFeatureLayer`) and `<map-extent>` groups,
 * keeping DOM z-order.
 *
 * `<map-tile>` renders both directly under `<map-layer>` (author light DOM — the
 * run joins the layer's own `ol/layer/Group`) and when grafted into a
 * `<map-link rel="features">`'s shadow root (the GeoServer layer-group-with-
 * raster response — the run joins the templated controller's group).
 */
/* global M */
import { Util } from './mapml/utils/Util.js';
import { calculatePosition } from './mapml/elementSupport/layers/calculatePosition.js';
import { MapTileLayer } from './mapml/layers/MapTileLayer.js';
import { toBounds as bounds } from './mapml/geometry/Bounds.js';
import { toPoint as point } from './mapml/geometry/Point.js';

export class HTMLTileElement extends HTMLElement {
  static get observedAttributes() {
    return ['row', 'col', 'zoom', 'src'];
  }

  get row() {
    return this._hasConnected
      ? +this._initialRow
      : +this.getAttribute('row');
  }
  set row(val) {
    if (this._hasConnected) return;
    const parsedVal = parseInt(val, 10);
    if (!isNaN(parsedVal)) {
      this.setAttribute('row', parsedVal);
    }
  }
  get col() {
    return this._hasConnected
      ? +this._initialCol
      : +this.getAttribute('col');
  }
  set col(val) {
    if (this._hasConnected) return;
    const parsedVal = parseInt(val, 10);
    if (!isNaN(parsedVal)) {
      this.setAttribute('col', parsedVal);
    }
  }
  get zoom() {
    return this._hasConnected
      ? +this._initialZoom
      : +this.getAttribute('zoom');
  }
  set zoom(val) {
    if (this._hasConnected) return;
    const parsedVal = parseInt(val, 10);
    if (!isNaN(parsedVal) && parsedVal >= 0 && parsedVal <= 25) {
      this.setAttribute('zoom', parsedVal);
    }
  }
  get src() {
    return this.hasAttribute('src') ? this.getAttribute('src') : '';
  }
  set src(val) {
    if (val) {
      this.setAttribute('src', val);
    }
  }
  // This tile's single-cell envelope (pcrs/gcrs/tcrs/tilematrix corners + zoom),
  // ported from MapML.js map-tile.js `get extent`. Lazily derived once and
  // cached on `_extent` (row/col/zoom are immutable after connect).
  get extent() {
    if (!this._extent) {
      this._calculateExtent();
    }
    return this._extent;
  }
  get position() {
    return calculatePosition(this);
  }

  constructor() {
    super();
  }

  getMapEl() {
    return Util.getClosest(this, 'mapml-viewer,map[is=web-map]');
  }
  getLayerEl() {
    return Util.getClosest(this, 'map-layer,layer-');
  }

  // row/col/zoom identify a fixed tilematrix cell and are immutable once
  // connected; only src may change (re-point the same cell). Ported from
  // MapML.js map-tile.js getAttribute/setAttribute overrides.
  getAttribute(name) {
    if (this._hasConnected) {
      switch (name) {
        case 'row':
          return String(this._initialRow);
        case 'col':
          return String(this._initialCol);
        case 'zoom':
          return String(this._initialZoom);
      }
    }
    return super.getAttribute(name);
  }
  setAttribute(name, value) {
    if (this._hasConnected && (name === 'row' || name === 'col' || name === 'zoom')) {
      return;
    }
    super.setAttribute(name, value);
  }

  async connectedCallback() {
    this._initialZoom = this.hasAttribute('zoom')
      ? +this.getAttribute('zoom')
      : this.getMapEl()?.zoom ?? 0;
    this._initialRow = this.hasAttribute('row') ? +this.getAttribute('row') : 0;
    this._initialCol = this.hasAttribute('col') ? +this.getAttribute('col') : 0;
    this._hasConnected = true;
    // Resolve the owning element: a light-DOM <map-layer>, or — when grafted
    // into a <map-link rel=features> shadow root — the shadow host.
    this._parentEl =
      this.parentNode.nodeName === 'MAP-LAYER' ||
      this.parentNode.nodeName === 'MAP-LINK'
        ? this.parentNode
        : this.parentNode.host;
    await this._createOrGetTileLayer();
  }

  disconnectedCallback() {
    // Decrement the owning element's layer registry for this position (captured
    // at connect time, since parentNode is already null here).
    const position = this._registryPosition ?? this.position;
    const registry = this._parentEl?._layerRegistry;
    const entry = registry?.get(position);
    if (entry) {
      entry.count--;
      if (entry.count === 0) {
        registry.delete(position);
      }
    }
    if (this._tileLayer) {
      this._tileLayer.removeMapTile(this);
      // Last tile in the run: drop the layer from its parent group.
      if (this._tileLayer._mapTiles.length === 0) {
        this._removeFromParent?.(this._tileLayer);
      }
      this._tileLayer = null;
    }
  }

  isFirst() {
    return !this._parentEl._layerRegistry.has(this.position);
  }

  getMeta(metaName) {
    const name = metaName.toLowerCase();
    if (name !== 'cs' && name !== 'zoom' && name !== 'projection') return;
    if (this._parentEl.nodeName === 'MAP-LINK') {
      return (
        this._parentEl.shadowRoot?.querySelector(
          `map-meta[name=${name}][content]`
        ) || this._parentEl._extent?.getMeta(name)
      );
    }
    return this._parentEl.src
      ? this._parentEl.shadowRoot?.querySelector(`map-meta[name=${name}][content]`)
      : this._parentEl.querySelector(`map-meta[name=${name}][content]`);
  }

  // Look up (or create) the MapTileLayer for this tile's position and add this
  // tile to it. Ported from MapML.js map-tile.js `_createOrGetTileLayer`
  // (`_templatedLayer` vs `_layer` branch).
  async _createOrGetTileLayer() {
    const viewer = this.getMapEl();
    if (viewer) await viewer.whenReady();
    if (!this.isConnected) return;
    const target = this._getTileTarget();
    if (!target) return;
    const { registry, add, remove } = target;
    // Capture position + remover now; parentNode is null by disconnect time.
    const position = this.position;
    this._registryPosition = position;
    this._removeFromParent = remove;
    if (!registry.has(position)) {
      this._tileLayer = new MapTileLayer({
        projection: viewer.projection,
        zIndex: position,
        nativeZoom: this.zoom
      });
      this._tileLayer.addMapTile(this);
      registry.set(position, { layer: this._tileLayer, count: 1 });
      add(this._tileLayer);
    } else {
      const entry = registry.get(position);
      this._tileLayer = entry.layer;
      entry.count++;
      this._tileLayer.addMapTile(this);
    }
  }

  // Resolve where this tile's MapTileLayer registers + attaches, honouring the
  // position-keyed registry. Under <map-link rel=features> the run joins the
  // templated controller's group; directly under <map-layer> it joins the
  // layer's own ol/layer/Group (interleaving with <map-feature>/<map-extent>
  // runs by calculatePosition). == MapML.js map-tile.js `_createOrGetTileLayer`
  // (`_templatedLayer` vs `_layer` branch).
  _getTileTarget() {
    const parent = this._parentEl;
    if (parent?.nodeName === 'MAP-LINK') {
      const controller = parent._featuresLayer;
      if (!controller || !parent._layerRegistry) return null;
      return {
        registry: parent._layerRegistry,
        add: (l) => controller.addLayer(l),
        remove: (l) => controller.removeLayer(l)
      };
    }
    if (parent?.nodeName === 'MAP-LAYER') {
      const group = parent.getLayerGroup();
      if (!group) return null;
      if (!parent._layerRegistry) parent._layerRegistry = new Map();
      return {
        registry: parent._layerRegistry,
        add: (l) => group.getLayers().push(l),
        remove: (l) => group.getLayers().remove(l)
      };
    }
    return null;
  }

  // Derive `_extent` from this tile's row/col/zoom cell. Ported from MapML.js
  // map-tile.js `_calculateExtent`: convert the tilematrix cell to a pixel box,
  // then to PCRS, then format. In OL the crs object is `M[projection]` (not
  // Leaflet's `map.options.crs`).
  _calculateExtent() {
    const mapEl = this.getMapEl();
    if (!mapEl || !mapEl._map) {
      // Can't calculate extent without a map
      return;
    }
    const projection = mapEl.projection;
    const tileSize = M[projection].options.crs.tile.bounds.max.x;

    // Convert tile coordinates to pixel bounds
    const pixelX = this.col * tileSize;
    const pixelY = this.row * tileSize;
    const pixelBounds = bounds(
      point(pixelX, pixelY),
      point(pixelX + tileSize, pixelY + tileSize)
    );

    // Convert pixel bounds to PCRS bounds
    const pcrsBounds = Util.pixelToPCRSBounds(pixelBounds, this.zoom, projection);

    // Format the extent similar to feature extents
    this._extent = Util._convertAndFormatPCRS(
      pcrsBounds,
      M[projection],
      projection
    );

    // Add zoom information
    this._extent.zoom = {
      minZoom: this.zoom,
      maxZoom: this.zoom,
      minNativeZoom: this.zoom,
      maxNativeZoom: this.zoom
    };
  }
}
