/**
 * `FeatureIndexControl` — top-right toggle button for the feature-index
 * accessibility overlay ({@link FeatureIndexOverlay}). Opt-in via
 * `controlslist="featureindex"`, mirroring MapML-MapLibre's control (MapML.js
 * itself gates the overlay only on the global `featureIndexOverlayOption`
 * preference and ships no button).
 *
 * The button drives the viewer's public `featureIndex` property (never the
 * overlay internals) and re-renders on the viewer's `mapml:featureindexchanged`
 * event. When a user/UA preference (`M.options.featureIndexOverlayOption`)
 * forces the state, the button reflects that pressed state but renders disabled
 * — an accessibility preference can't be overridden from the map UI.
 */
import Control from 'ol/control/Control.js';
import { featureIndexPreference } from '../layers/FeatureIndexOverlay.js';

export class FeatureIndexControl extends Control {
  constructor(viewer) {
    const container = document.createElement('div');
    container.className = 'mapml-feature-index-button ol-control';

    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'mapml-button';

    const icon = document.createElement('span');
    icon.className = 'mapml-feature-index-button-icon';
    icon.setAttribute('aria-hidden', 'true');
    button.appendChild(icon);
    container.appendChild(button);

    super({ element: container });

    this._viewer = viewer;
    this._button = button;

    this._onClick = (event) => {
      event.stopPropagation();
      // A user/UA preference overrides the map UI: can't toggle when forced.
      if (featureIndexPreference() !== undefined) return;
      this._viewer.featureIndex = !this._viewer.featureIndex;
    };
    this._onChanged = () => this._render();

    button.addEventListener('click', this._onClick);
    viewer.addEventListener('mapml:featureindexchanged', this._onChanged);
    this._render();
  }

  // Remove listeners when the control is uninstalled (controlslist change).
  destroy() {
    this._button.removeEventListener('click', this._onClick);
    this._viewer.removeEventListener('mapml:featureindexchanged', this._onChanged);
  }

  _render() {
    const forced = featureIndexPreference() !== undefined;
    const active = this._viewer.featureIndex;
    const label = this._viewer.locale.btnFeatureIndex;
    this._button.title = label;
    this._button.setAttribute('aria-label', label);
    this._button.setAttribute('aria-pressed', String(active));
    this._button.disabled = forced;
    if (forced) this._button.setAttribute('aria-disabled', 'true');
    else this._button.removeAttribute('aria-disabled');
  }
}
