/**
 * `ScaleBar` — bottom-left control showing the map scale, ported from MapML.js
 * `src/mapml/control/ScaleBar.js` (a Leaflet `Control.Scale` subclass) to an
 * OpenLayers `ol/control/Control` wrapping `ol/control/ScaleLine` (the OL analog
 * of Leaflet's scale line).
 *
 * a11y contract (the reason MapML.js wraps the plain scale line): the outer
 * container is a tab stop (`tabindex=0`) carrying an `aria-label` that spells the
 * scale out in full words — e.g. "2.6 centimeters to 100 meters" — and a visually
 * hidden `role=status aria-live=polite` output (`.mapml-screen-reader-output-scale`)
 * re-announces it whenever the map is zoomed/panned or (re)focused, so screen
 * reader users hear the current scale. The unit abbreviations produced by the
 * scale line ("m", "km", "ft", "mi") are expanded to words for that text.
 *
 * metric vs imperial follows `M.options.announceScale` (the MapML.js option),
 * normalized here the same way MapML.js normalizes it.
 */
import Control from 'ol/control/Control.js';
import ScaleLine from 'ol/control/ScaleLine.js';

export class ScaleBar extends Control {
  constructor(viewer) {
    const container = document.createElement('div');
    // `.ol-control` gives the wrapper OL's absolute corner positioning; the CSS
    // resets its chrome so only the scale line shows. `tabindex=0` makes it a
    // tab stop whose `aria-label` a screen reader reads (MapML.js does the same).
    container.className = 'mapml-control-scale ol-unselectable ol-control';
    container.setAttribute('tabindex', '0');
    super({ element: container });

    this._viewer = viewer;

    // Normalize M.options.announceScale exactly like MapML.js's viewer, then
    // pick the single unit family OL's ScaleLine renders (Leaflet could show two
    // lines; the common/default case is metric-only).
    let scaleValue = window.M.options.announceScale;
    if (scaleValue === 'metric') scaleValue = { metric: true, imperial: false };
    if (scaleValue === 'imperial') scaleValue = { metric: false, imperial: true };
    this._metric = !(scaleValue && scaleValue.metric === false);

    this._scaleLine = new ScaleLine({
      units: this._metric ? 'metric' : 'imperial',
      target: container
    });
  }

  setMap(map) {
    const prev = this.getMap();
    if (prev && !map) {
      this._teardown(prev);
    }
    super.setMap(map);
    if (map) {
      // Render the scale line into our container (target set in the ctor) and
      // register it so OL updates it each frame.
      map.addControl(this._scaleLine);

      // Visually hidden live region (the OL analog of MapML.js inserting the
      // output into map._container is the map viewport).
      const output = document.createElement('output');
      output.setAttribute('role', 'status');
      output.setAttribute('aria-live', 'polite');
      output.setAttribute('aria-atomic', 'true');
      output.className = 'mapml-screen-reader-output-scale';
      map.getViewport().appendChild(output);
      this._output = output;

      this._onMoveEnd = () => this._updateOutput();
      map.on('moveend', this._onMoveEnd);

      // MapML.js re-announces on focus of map._container, which Leaflet focuses
      // from both keyboard and pointer. OL splits those: keyboard focus rests on
      // the viewer host, pointer focus on the viewport (tabindex=-1) — listen on
      // both so either entry point re-announces the scale like MapML.js.
      this._onFocus = () => this._focusOutput();
      this._viewer.addEventListener('focus', this._onFocus);
      map.getViewport().addEventListener('focus', this._onFocus);

      // Run once on load (the scale line has no measured width until the first
      // frame renders).
      setTimeout(() => {
        this._updateOutput();
        this._focusOutput();
      }, 0);
    }
  }

  destroy() {
    const map = this.getMap();
    if (map) this._teardown(map);
    super.disposeInternal?.();
  }

  _teardown(map) {
    map.un('moveend', this._onMoveEnd);
    this._viewer.removeEventListener('focus', this._onFocus);
    map.getViewport().removeEventListener('focus', this._onFocus);
    map.removeControl(this._scaleLine);
    this._output?.remove();
    this._output = null;
  }

  _pixelsToDistance(px, units) {
    const dpi = window.devicePixelRatio * 96; // default dpi
    if (units === 'metric') {
      return (px / dpi) * 2.54; // inches to cm
    }
    return px / dpi;
  }

  // Width, in CSS pixels, of the rendered scale line (OL sets it as an inline
  // `style.width`, the analog of the Leaflet style MapML.js parses).
  _scaleLength(inner) {
    return parseInt(inner.style.width, 10) || inner.offsetWidth;
  }

  _focusOutput() {
    setTimeout(() => {
      if (!this._output) return;
      // Clear then re-set so the live region re-announces even when the text
      // is unchanged (MapML.js does the same two-step).
      this._output.textContent = '';
      setTimeout(() => {
        if (this._output) {
          this._output.textContent = this.element.getAttribute('aria-label');
        }
      }, 100);
    }, 0);
  }

  _updateOutput() {
    const inner = this.element.querySelector('.ol-scale-line-inner');
    if (!inner) return;
    const px = this._scaleLength(inner);
    let output = '';
    if (this._metric) {
      const distance = parseFloat(
        this._pixelsToDistance(px, 'metric').toFixed(1)
      );
      output = `${distance} centimeters to ${inner.textContent.trim()}`;
      output = output.replace(/(\d+)\s*m\b/g, '$1 meters');
      output = output.replace(/ km/g, ' kilometers');
    } else {
      const distance = parseFloat(
        this._pixelsToDistance(px, 'imperial').toFixed(1)
      );
      output = `${distance} inches to ${inner.textContent.trim()}`;
      output = output.replace(/ft/g, 'feet');
      output = output.replace(/mi/g, 'miles');
    }
    this.element.setAttribute('aria-label', output);
    if (this._output) this._output.textContent = output;
  }
}
