/**
 * `FullscreenButton` — top-left control that toggles fullscreen on the whole
 * `<mapml-viewer>` host (so the shadow-DOM controls come along). Ported from
 * MapML.js `src/mapml/control/FullscreenButton.js` (a Leaflet `Control` that
 * calls `map.toggleFullscreen()`) to an OpenLayers `ol/control/Control` that
 * drives the viewer's public `toggleFullScreen()`.
 *
 * The button title flips between `btnFullScreen` and `btnExitFullScreen` on
 * `fullscreenchange`, mirroring MapML.js's `_toggleTitle`.
 */
import Control from 'ol/control/Control.js';

export class FullscreenButton extends Control {
  constructor(viewer) {
    const container = document.createElement('div');
    container.className = 'mapml-fullscreen-button ol-control';

    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'mapml-button';
    const icon = document.createElement('span');
    icon.className = 'mapml-fullscreen-button-icon';
    icon.setAttribute('aria-hidden', 'true');
    button.appendChild(icon);
    container.appendChild(button);

    super({ element: container });

    this._viewer = viewer;
    this._button = button;

    this._onClick = (event) => {
      event.stopPropagation();
      viewer.toggleFullScreen();
    };
    this._onFullscreenChange = () => this._update();

    button.addEventListener('click', this._onClick);
    document.addEventListener('fullscreenchange', this._onFullscreenChange);
    this._update();
  }

  destroy() {
    this._button.removeEventListener('click', this._onClick);
    document.removeEventListener('fullscreenchange', this._onFullscreenChange);
  }

  _update() {
    const inFullscreen = document.fullscreenElement === this._viewer;
    const locale = this._viewer.locale;
    const title = inFullscreen ? locale.btnExitFullScreen : locale.btnFullScreen;
    this._button.title = title;
    this._button.setAttribute('aria-label', title);
    this._button.classList.toggle('is-fullscreen', inFullscreen);
  }
}
