/**
 * `MapFeatureLayer` — the OpenLayers analog of MapML.js's
 * `src/mapml/layers/MapFeatureLayer.js` (a Leaflet `FeatureGroup`). One
 * instance per `<map-layer>` holds that layer's static `<map-feature>`
 * geometries; it is added to the layer's `ol/layer/Group` (the `_mapmlvectors`
 * member read by `HTMLLayerElement._calculateBounds`).
 *
 * Rendering is re-architected onto `ol/layer/Vector` + `ol/source/Vector`
 * (canvas) rather than Leaflet's SVG renderer. `createGeometry` mirrors the
 * upstream method name: it parses a `<map-feature>`'s `<map-geometry>` into an
 * `ol/Feature` (PCRS coordinates); `addLayer`/`removeLayer` add/remove that
 * feature and recompute `layerBounds`/`zoomBounds`.
 *
 * First slice: static features only, a single default style. Per-feature
 * styling (class -> style), interactivity, popups and a11y focus land later.
 *
 * Feature styling: OpenLayers renders features to a canvas (no per-feature DOM
 * for CSS to select), so author `<map-style>`/`<map-link rel=stylesheet>` CSS is
 * applied via hidden per-feature "probe" elements (see resolveStyle.js). Until
 * an author style is rendered, features keep the layer DEFAULT_STYLE.
 */
import VectorLayer from 'ol/layer/Vector.js';
import VectorSource from 'ol/source/Vector.js';
import Feature from 'ol/Feature.js';
import Style from 'ol/style/Style.js';
import Stroke from 'ol/style/Stroke.js';
import Fill from 'ol/style/Fill.js';
import CircleStyle from 'ol/style/Circle.js';
import { parseGeometry } from '../features/parseGeometry.js';
import {
  resolveFeatureStyle,
  geomKindFor
} from '../features/resolveStyle.js';
import { renderStyles } from '../elementSupport/layers/renderStyles.js';
import { toBounds as bounds } from '../geometry/Bounds.js';
import { toPoint as point } from '../geometry/Point.js';

const SVG_NS = 'http://www.w3.org/2000/svg';

// Resolve a feature's effective style class. MapML.js renders one SVG path per
// geometry child, so authors (and geojson2mapml's geometryFunction) put the
// class on the geometry element (<map-polygon class>, <map-multipolygon>'s
// child <map-polygon>s), NOT on <map-feature>. Read the geometry shape's class
// first (unwrapping <map-a>/<map-span>, hoisting a multi-* wrapper's first
// classed child), then fall back to a class on <map-feature> itself.
function featureStyleClass(featureEl) {
  let shape = featureEl?.querySelector('map-geometry')?.firstElementChild;
  while (shape && (shape.nodeName === 'MAP-A' || shape.nodeName === 'MAP-SPAN')) {
    shape = shape.firstElementChild;
  }
  let cls = shape?.getAttribute('class');
  if (!cls && shape) {
    cls = shape.querySelector('[class]')?.getAttribute('class') || null;
  }
  return cls || featureEl?.getAttribute('class') || null;
}

// MapML.js default feature style (src/mapml/features/path.js defaults):
// #3388ff stroke, translucent fill, radius-6 point markers.
const DEFAULT_STYLE = new Style({
  stroke: new Stroke({ color: '#3388ff', width: 3 }),
  fill: new Fill({ color: 'rgba(51, 136, 255, 0.2)' }),
  image: new CircleStyle({
    radius: 6,
    stroke: new Stroke({ color: '#3388ff', width: 3 }),
    fill: new Fill({ color: 'rgba(51, 136, 255, 0.2)' })
  })
});

export class MapFeatureLayer extends VectorLayer {
  constructor(options = {}) {
    super({ source: new VectorSource(), style: DEFAULT_STYLE });
    this._projection = options.projection;
    this._mapEl = options.mapEl;
    // ol/Feature instances added via addLayer, for bounds recomputation.
    this._features = [];
    // Set true once an author `<map-style>`/`rel=stylesheet` is rendered; until
    // then features keep the layer's DEFAULT_STYLE (no per-feature resolution).
    this._hasAuthorStyles = false;
  }

  // Lazily build the hidden shadow-DOM container that holds the injected author
  // CSS and the per-feature style probes. getComputedStyle over the probes
  // resolves each feature's style through the real cascade (see resolveStyle.js).
  _ensureContainer() {
    if (this._container) return;
    const host = this._mapEl?._container;
    if (!host) return;
    const div = document.createElement('div');
    div.className = 'mapml-style-container';
    div.setAttribute('aria-hidden', 'true');
    div.style.cssText =
      'position:absolute;width:0;height:0;overflow:hidden;visibility:hidden;pointer-events:none;';
    const svg = document.createElementNS(SVG_NS, 'svg');
    svg.setAttribute('class', 'mapml-style-probe');
    div.appendChild(svg);
    host.appendChild(div);
    this._container = div;
    this._probeSvg = svg;
  }

  // Insert a <map-style>/<map-link rel=stylesheet>-generated <style>/<link>
  // into the container, then re-resolve every feature's style. Called by
  // map-style._connect / map-link._createStylesheetLink (== MapML.js
  // layer.renderStyles).
  renderStyles(styleOrLink) {
    this._ensureContainer();
    if (!this._container) return;
    this._hasAuthorStyles = true;
    renderStyles.call(this, styleOrLink);
    this._restyleFeatures();
  }

  // Ensure a hidden probe element (carrying the feature's class/id) exists for
  // a feature, so its computed style can be read.
  _ensureProbe(olFeature) {
    this._ensureContainer();
    if (!this._probeSvg) return;
    const featureEl = olFeature._featureEl;
    const kind = geomKindFor(olFeature.getGeometry());
    if (!olFeature._probe) {
      const el = document.createElementNS(
        SVG_NS,
        kind === 'point' ? 'circle' : 'path'
      );
      el.setAttribute('stroke', '#3388ff');
      el.setAttribute('stroke-opacity', '1');
      el.setAttribute('stroke-width', '3');
      el.setAttribute('stroke-linecap', 'round');
      el.setAttribute('stroke-linejoin', 'round');
      if (kind === 'point') {
        el.setAttribute('r', '6');
        el.setAttribute('fill', '#3388ff');
        el.setAttribute('fill-opacity', '0.2');
      } else if (kind === 'polygon') {
        el.setAttribute('fill', '#3388ff');
        el.setAttribute('fill-opacity', '0.2');
      } else {
        el.setAttribute('fill', 'none');
      }
      olFeature._probe = el;
      this._probeSvg.appendChild(el);
    }
    const cls = featureStyleClass(featureEl);
    if (cls) olFeature._probe.setAttribute('class', cls);
    else olFeature._probe.removeAttribute('class');
    const id = featureEl?.getAttribute('id');
    if (id) olFeature._probe.setAttribute('id', id);
    else olFeature._probe.removeAttribute('id');
  }

  // Re-resolve every feature's ol/style from its probe's computed style.
  _restyleFeatures() {
    if (!this._hasAuthorStyles) return;
    for (const f of this._features) {
      this._ensureProbe(f);
      if (!f._probe) continue;
      f.setStyle(resolveFeatureStyle(f._probe, geomKindFor(f.getGeometry())));
    }
    this.changed();
  }

  // Parse a <map-feature> into an ol/Feature (PCRS coords). Mirrors the
  // upstream MapFeatureLayer.createGeometry signature.
  createGeometry(featureEl, fallbackCS) {
    const geomEl = featureEl.querySelector('map-geometry');
    if (!geomEl) return null;
    const { geometry, bounds: pcrsBounds, link } = parseGeometry(geomEl, {
      projection: this._projection,
      zoom: featureEl.zoom,
      fallbackCS
    });
    if (!geometry) return null;
    const olFeature = new Feature({ geometry });
    olFeature._featureEl = featureEl;
    olFeature._pcrsBounds = pcrsBounds;
    olFeature._zoomBounds = featureEl._getZoomBounds();
    // A <map-a>-wrapped geometry is a hyperlink: stamp the link so
    // FeatureInteraction dispatches Util._handleLink on click instead of a popup.
    if (link) olFeature._featureLink = link;
    return olFeature;
  }

  addLayer(olFeature) {
    this.getSource().addFeature(olFeature);
    this._features.push(olFeature);
    if (this._hasAuthorStyles) {
      this._ensureProbe(olFeature);
      if (olFeature._probe) {
        olFeature.setStyle(
          resolveFeatureStyle(olFeature._probe, geomKindFor(olFeature.getGeometry()))
        );
      }
    }
    this._calculateLayerBounds();
    this._mapEl?._featureIndex?.scheduleRefresh();
  }

  removeLayer(olFeature) {
    this.getSource().removeFeature(olFeature);
    this._features = this._features.filter((f) => f !== olFeature);
    if (olFeature._probe) {
      olFeature._probe.remove();
      delete olFeature._probe;
    }
    this._calculateLayerBounds();
    this._mapEl?._featureIndex?.scheduleRefresh();
  }

  // Union of member features' PCRS bounds + zoom bounds. Read by
  // HTMLLayerElement._calculateBounds to build the layer extent.
  _calculateLayerBounds() {
    let bnds, zoomBounds;
    for (const f of this._features) {
      if (f._pcrsBounds) {
        if (!bnds) {
          bnds = bounds(f._pcrsBounds.min, f._pcrsBounds.max);
        } else {
          bnds.extend(f._pcrsBounds);
        }
      }
      if (f._zoomBounds) {
        if (!zoomBounds) {
          zoomBounds = Object.assign({}, f._zoomBounds);
        } else {
          zoomBounds.minZoom = Math.min(zoomBounds.minZoom, f._zoomBounds.minZoom);
          zoomBounds.maxZoom = Math.max(zoomBounds.maxZoom, f._zoomBounds.maxZoom);
          zoomBounds.minNativeZoom = Math.min(
            zoomBounds.minNativeZoom,
            f._zoomBounds.minNativeZoom
          );
          zoomBounds.maxNativeZoom = Math.max(
            zoomBounds.maxNativeZoom,
            f._zoomBounds.maxNativeZoom
          );
        }
      }
    }
    this.layerBounds = bnds;
    this.zoomBounds = zoomBounds;
  }

  // Whether this feature run is within zoom range and overlaps the current
  // view. Ported from MapML.js MapFeatureLayer.isVisible; OL's view extent is
  // already PCRS. Named `_isVisible` (not `isVisible`) for the same reason as
  // MapTileLayer: ol/layer/Layer already defines an `isVisible(view)` used by
  // getAttributions.
  _isVisible(map) {
    if (!this.layerBounds || !this.zoomBounds) return false;
    const view = map.getView();
    const zoom = Math.round(view.getZoom());
    if (zoom < this.zoomBounds.minZoom || zoom > this.zoomBounds.maxZoom) {
      return false;
    }
    const [minX, minY, maxX, maxY] = view.calculateExtent(map.getSize());
    return this.layerBounds.overlaps(bounds(point(minX, minY), point(maxX, maxY)));
  }
}
