/*
 * `TemplatedPMTilesLayer` — OL analog of MapML.js
 * src/mapml/layers/TemplatedPMTilesLayer.js. Renders a
 * `<map-link rel="tile">` VECTOR tile source as an `ol/layer/VectorTile`,
 * styled by a sibling
 * `<map-link rel="stylesheet" type="application/vnd.maplibre-style+json">`.
 * Like MapML.js's file of the same name it drives BOTH vector-tile flavours:
 *   - `type="application/pmtiles"`            → an `ol-pmtiles`
 *     `PMTilesVectorSource` (tile grid read from the archive header, so the
 *     512px-tile data-zoom offset is handled for us);
 *   - `type="application/vnd.mapbox-vector-tile"` → a plain
 *     `ol/source/VectorTile` + `ol/format/MVT` on the extent's MapML tile grid
 *     (WMTS tilematrix zoom == map zoom, 1:1, like the raster tile path).
 *
 * Divergence from MapML.js (deliberate, user-preferred): MapML.js drives
 * protomaps-leaflet with an idiosyncratic ES-module rules sheet
 * (`application/pmtiles+stylesheet`). This port adopts the MapML-MapLibre
 * contract instead — a Mapbox/MapLibre style-spec JSON (`{ version, layers[] }`)
 * carried by an `application/vnd.maplibre-style+json` stylesheet link — because
 * those styles are Mapbox-based and far less idiosyncratic. `ol-mapbox-style`'s
 * low-level `stylefunction` compiles the style layers into an OL style function.
 *
 * `stylefunction` requires the style object to declare its `sources` and each
 * style layer to reference one by `source` id; the MapML style link carries
 * only `layers[]` (its data source is injected at render time), so a synthetic
 * vector `sources` entry is added and each layer stamped with it.
 */
import VectorTileLayer from 'ol/layer/VectorTile.js';
import VectorTileSource from 'ol/source/VectorTile.js';
import MVT from 'ol/format/MVT.js';
import { PMTilesVectorSource } from 'ol-pmtiles';
import { stylefunction } from 'ol-mapbox-style';

// The synthetic source id the style layers are bound to (see file header).
const SOURCE_ID = 'mapml-vector';

export class TemplatedPMTilesLayer {
  constructor(templateVars, options) {
    this._template = templateVars;
    this._linkEl = options.linkEl;
    this.zoomBounds = options.zoomBounds;
    this.extentBounds = options.extentBounds;

    const source =
      options.type === 'mvt'
        ? new VectorTileSource({
            projection: options.projection,
            tileGrid: options.tileGrid,
            format: new MVT(),
            url: options.url,
            attributions: options.attributions
          })
        : new PMTilesVectorSource({
            url: options.url,
            attributions: options.attributions
          });
    const layer = new VectorTileLayer({
      declutter: true,
      source,
      zIndex: options.zIndex
    });
    // Constrain display zoom + geographic extent from the extent's derived
    // bounds, mirroring the raster tile path in map-link.js `_applyTile`. OL's
    // layer minZoom is exclusive, so subtract 1 to keep the inclusive MapML
    // minZoom visible.
    if (this.zoomBounds) {
      layer.setMinZoom(this.zoomBounds.minZoom - 1);
      layer.setMaxZoom(this.zoomBounds.maxZoom);
    }
    if (this.extentBounds) {
      layer.setExtent([
        this.extentBounds.min.x,
        this.extentBounds.min.y,
        this.extentBounds.max.x,
        this.extentBounds.max.y
      ]);
    }
    this._applyGlStyle(layer, options.glStyle);
    this._layer = layer;
  }

  // Compile the MapLibre style-spec `layers[]` into an OL style function. The
  // synthetic vector `sources` entry + per-layer `source` stamp satisfy
  // stylefunction's requirement without changing the author's paint/layout.
  _applyGlStyle(layer, glStyle) {
    if (!glStyle) return;
    const glStyleForOL = {
      version: 8,
      sources: { [SOURCE_ID]: { type: 'vector' } },
      layers: (glStyle.layers || []).map((l) =>
        l.source ? l : { ...l, source: SOURCE_ID }
      )
    };
    stylefunction(layer, glStyleForOL, SOURCE_ID);
  }

  getLayer() {
    return this._layer;
  }

  destroy() {
    this._layer?.getSource()?.clear?.();
    this._layer = null;
  }
}

export function templatedPMTilesLayer(templateVars, options) {
  return new TemplatedPMTilesLayer(templateVars, options);
}
