/**
 * Stylesheet for the {@link ContextMenu} overlay, injected into the viewer's
 * shadow root. Ported from the MapML-MapLibre port's `contextMenu.css.ts`
 * (which in turn mirrors MapML.js's `.mapml-contextmenu` rules), trimmed to
 * the items shipped so far. The menu is a sibling of the OpenLayers map inside
 * `.mapml-container` (position: relative), so it positions freely over the
 * canvas.
 */
export const contextMenuCss = /* css */ `
.mapml-contextmenu {
  position: absolute;
  z-index: 10000;
  min-width: 200px;
  padding: 4px 0;
  margin: 0;
  background: #fff;
  border: 1px solid #999;
  border-radius: 4px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.25);
  font: 13px/1.4 sans-serif;
  color: #222;
  list-style: none;
  user-select: none;
}
.mapml-contextmenu[hidden] {
  display: none;
}
.mapml-contextmenu-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  width: 100%;
  padding: 4px 12px;
  background: none;
  border: 0;
  text-align: left;
  font: inherit;
  color: inherit;
  cursor: pointer;
}
.mapml-contextmenu-item:hover:not(:disabled),
.mapml-contextmenu-item:focus:not(:disabled) {
  background: #2a72d4;
  color: #fff;
  outline: none;
}
.mapml-contextmenu-item:disabled {
  color: #aaa;
  cursor: default;
}
.mapml-contextmenu-item kbd {
  margin-left: 12px;
  padding: 1px 4px;
  font-family: inherit;
  font-size: 11px;
  color: #555;
  background: #eee;
  border: 1px solid #ccc;
  border-radius: 3px;
}
.mapml-contextmenu-item:hover:not(:disabled) kbd,
.mapml-contextmenu-item:focus:not(:disabled) kbd {
  color: #eee;
  background: rgba(255, 255, 255, 0.15);
  border-color: rgba(255, 255, 255, 0.3);
}
.mapml-contextmenu-separator {
  height: 1px;
  margin: 4px 0;
  background: #ddd;
}
`;
