/**
 * Right-click / keyboard-activated context menu for `<mapml-viewer>`, ported
 * from MapML.js's `src/mapml/handlers/ContextMenu.js` to a framework-neutral
 * class (the same approach the MapML-MapLibre port takes in
 * `src/controls/ContextMenu.ts`). It is not an `ol/control/Control`: it mounts
 * a plain menu element into the viewer's shadow root and drives OpenLayers via
 * the viewer's public API, so its behaviour and DOM stay diffable against the
 * two sibling ports.
 *
 * Item set (order + shortcut hints from MapML.js): Back / Forward / Reload /
 * Fullscreen / Copy / Paste / Toggle Controls / Debug / View Source.
 *
 * Keyboard semantics mirror MapML.js:
 *   Map-wide (menu closed, viewer focused):
 *     - Alt+ArrowLeft  → back()
 *     - Alt+ArrowRight → forward()
 *     - Ctrl+R         → reload() (only when there is history to reset to;
 *                        otherwise the browser's own reload is left alone)
 *     - ContextMenu / Shift+F10 → open the menu at the viewport centre
 *   Menu-open:
 *     - ArrowUp / ArrowDown / Home / End → navigate
 *     - Enter / Space → activate focused item
 *     - F → toggle fullscreen
 *     - Escape / ContextMenu → close
 */
import { MapKeyboard } from './MapKeyboard.js';
import { Util } from '../utils/Util.js';
import { toBounds as bounds } from '../geometry/Bounds.js';

export class ContextMenu {
  constructor(viewer) {
    this._viewer = viewer;
    this._map = viewer.map;
    this._locale = viewer.locale;
    this._activeIndex = 0;
    this._wasOpenedByKeyboard = false;
    // The layer/extent context menu currently open (null when none).
    this._openLayerMenuEl = null;
    this._layerClicked = null;
    // The map location (view/PCRS coordinate) + pixel the menu was opened at,
    // used by the Copy submenu's location/extent operations.
    this._clickCoordinate = null;
    this._clickPixel = null;
    // Default coordinate systems for Copy Extent / Copy Location. Ported from
    // MapML.js ContextMenu.js (`defExtCS`/`defLocCS`, seeded from M.options and
    // settable at runtime for tests / the extension's coordinate preferences).
    this.defExtCS = window.M?.options?.defaultExtCoor;
    this.defLocCS = window.M?.options?.defaultLocCoor;

    this._menu = document.createElement('div');
    this._menu.className = 'mapml-contextmenu';
    this._menu.setAttribute('role', 'menu');
    this._menu.setAttribute('tabindex', '-1');
    this._menu.hidden = true;
    // Mounted inside .mapml-container (position: relative) so pixel
    // coordinates from OpenLayers map events place it directly.
    viewer._container.appendChild(this._menu);

    this._buildItems();
    this._buildCopySubMenu();
    this._buildLayerMenus();

    this._onMapContextMenu = this._onMapContextMenu.bind(this);
    this._onDocumentMouseDown = this._onDocumentMouseDown.bind(this);
    this._onDocumentKeyDown = this._onDocumentKeyDown.bind(this);
    this._onFullscreenChange = this._syncFullscreenLabel.bind(this);
    this._onMenuKeyDown = this._onMenuKeyDown.bind(this);

    this._map.on('contextmenu', this._onMapContextMenu);
    this._menu.addEventListener('keydown', this._onMenuKeyDown);
    document.addEventListener('mousedown', this._onDocumentMouseDown, true);
    document.addEventListener('keydown', this._onDocumentKeyDown);
    document.addEventListener('fullscreenchange', this._onFullscreenChange);

    this._updateEnabledState();
  }

  destroy() {
    this._map.un('contextmenu', this._onMapContextMenu);
    this._menu.removeEventListener('keydown', this._onMenuKeyDown);
    document.removeEventListener('mousedown', this._onDocumentMouseDown, true);
    document.removeEventListener('keydown', this._onDocumentKeyDown);
    document.removeEventListener('fullscreenchange', this._onFullscreenChange);
    this._menu.remove();
    this._copySubMenu?.remove();
    this._layerMenuEl?.remove();
    this._extentMenuEl?.remove();
  }

  _buildItems() {
    const L = this._locale;
    // Order + shortcut hints match MapML.js's ContextMenu.js items 0–3.
    const defs = [
      {
        id: 'back',
        label: L.cmBack,
        kbd: 'Alt+Left Arrow',
        run: () => this._viewer.back(),
        isEnabled: () => this._historyState().canBack
      },
      {
        id: 'forward',
        label: L.cmForward,
        kbd: 'Alt+Right Arrow',
        run: () => this._viewer.forward(),
        isEnabled: () => this._historyState().canForward
      },
      {
        id: 'reload',
        label: L.cmReload,
        kbd: 'Ctrl+R',
        run: () => this._viewer.reload(),
        isEnabled: () => this._historyState().canReload
      },
      {
        id: 'fullscreen',
        label: L.btnFullScreen,
        kbd: 'F',
        run: () => this._viewer.toggleFullScreen()
      },
      { separator: true },
      {
        id: 'copy',
        label: L.cmCopyCoords,
        kbd: 'C',
        submenu: true
      },
      {
        id: 'paste',
        label: L.cmPasteLayer,
        kbd: 'P',
        run: () => this._paste()
      },
      { separator: true },
      {
        id: 'toggle-controls',
        label: L.cmToggleControls,
        kbd: 'T',
        run: () => this._viewer.toggleControls()
      },
      {
        id: 'debug',
        label: L.cmToggleDebug,
        kbd: 'D',
        run: () => this._viewer.toggleDebug()
      },
      {
        id: 'view-source',
        label: L.cmViewSource,
        kbd: 'V',
        run: () => this._viewer.viewSource()
      }
    ];

    this._items = [];
    for (const def of defs) {
      if (def.separator) {
        const sep = document.createElement('div');
        sep.className = 'mapml-contextmenu-separator';
        sep.setAttribute('role', 'separator');
        this._menu.appendChild(sep);
        continue;
      }
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'mapml-contextmenu-item';
      btn.setAttribute('role', 'menuitem');
      btn.dataset.id = def.id;
      btn.tabIndex = -1;
      btn.innerHTML = `<span>${def.label}</span><kbd>${def.kbd}</kbd>`;
      if (def.submenu) {
        // "Copy" opens a submenu rather than running a single action.
        btn.setAttribute('aria-haspopup', 'true');
        btn.setAttribute('aria-expanded', 'false');
        btn.setAttribute('aria-controls', 'mapml-copy-submenu');
        this._copyItemEl = btn;
        btn.addEventListener('click', () => this._toggleCopySubMenu());
        btn.addEventListener('mouseenter', () => this._showCopySubMenu());
      } else {
        btn.addEventListener('mouseenter', () => this._hideCopySubMenu());
        btn.addEventListener('click', () => {
          if (btn.disabled) return;
          def.run();
          this.close();
        });
      }
      this._menu.appendChild(btn);
      this._items.push({
        el: btn,
        id: def.id,
        isEnabled: def.isEnabled ?? (() => true)
      });
    }
  }

  _historyState() {
    return (
      this._viewer._history?.getState() ?? {
        canBack: false,
        canForward: false,
        canReload: false
      }
    );
  }

  _updateEnabledState() {
    for (const item of this._items) {
      const enabled = item.isEnabled();
      item.el.disabled = !enabled;
      item.el.setAttribute('aria-disabled', enabled ? 'false' : 'true');
    }
    this._syncFullscreenLabel();
  }

  _syncFullscreenLabel() {
    const item = this._items?.find((it) => it.id === 'fullscreen');
    if (!item) return;
    const inFs = document.fullscreenElement === this._viewer;
    const label = inFs
      ? this._locale.btnExitFullScreen
      : this._locale.btnFullScreen;
    item.el.innerHTML = `<span>${label}</span><kbd>F</kbd>`;
  }

  // Read the clipboard and delegate to Util._pasteLayer, which appends a
  // <map-layer> to the viewer for pasted <map-layer>/<map-feature> markup, a
  // URL (as <map-layer src>), or GeoJSON. Ported from MapML.js ContextMenu._paste.
  _paste() {
    navigator.clipboard.readText().then((text) => {
      Util._pasteLayer(this._viewer, text);
    });
  }

  // ---- Copy submenu -------------------------------------------------------
  // Ported from MapML.js ContextMenu.js item 5 (`_copyCoords` + `_copySubMenu`
  // with Map / Extent / Location). The submenu is a sibling of the map menu in
  // .mapml-container; hover or ArrowRight/C opens it beside the "Copy" item.
  _buildCopySubMenu() {
    const L = this._locale;
    const menu = document.createElement('div');
    menu.className = 'mapml-contextmenu mapml-submenu';
    menu.id = 'mapml-copy-submenu';
    menu.setAttribute('role', 'menu');
    menu.setAttribute('tabindex', '-1');
    menu.hidden = true;
    const defs = [
      { id: 'copy-map', label: L.cmCopyMapML, run: () => this._copyMapML() },
      { id: 'copy-extent', label: L.cmCopyExtent, run: () => this._copyExtent() },
      {
        id: 'copy-location',
        label: L.cmCopyLocation,
        run: () => this._copyLocation()
      }
    ];
    const items = [];
    for (const def of defs) {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'mapml-contextmenu-item';
      btn.setAttribute('role', 'menuitem');
      btn.dataset.id = def.id;
      btn.tabIndex = -1;
      btn.innerHTML = `<span>${def.label}</span>`;
      btn.addEventListener('click', () => {
        def.run();
        this.close();
      });
      menu.appendChild(btn);
      items.push({ el: btn, run: def.run });
    }
    menu._items = items;
    menu._activeIndex = 0;
    menu.addEventListener('keydown', (e) => this._onCopySubMenuKeyDown(e));
    menu.addEventListener('mouseleave', (e) => this._hideCopySubMenuIfOutside(e));
    this._viewer._container.appendChild(menu);
    this._copySubMenu = menu;
  }

  _toggleCopySubMenu() {
    if (this._copySubMenu.hidden) this._showCopySubMenu();
    else this._hideCopySubMenu();
  }

  _showCopySubMenu() {
    if (!this._copySubMenu || !this._copySubMenu.hidden) return;
    this._copyItemEl?.setAttribute('aria-expanded', 'true');
    this._copySubMenu.hidden = false;
    this._positionCopySubMenu();
  }

  _hideCopySubMenu() {
    if (!this._copySubMenu || this._copySubMenu.hidden) return;
    this._copySubMenu.hidden = true;
    this._copyItemEl?.setAttribute('aria-expanded', 'false');
  }

  _hideCopySubMenuIfOutside(e) {
    const to = e.relatedTarget;
    if (to && (this._copySubMenu.contains(to) || to === this._copyItemEl)) {
      return;
    }
    this._hideCopySubMenu();
  }

  _positionCopySubMenu() {
    const menu = this._menu;
    const sub = this._copySubMenu;
    const size = this._map.getSize() ?? [0, 0];
    let left = menu.offsetLeft + menu.offsetWidth;
    if (left + sub.offsetWidth > size[0]) {
      left = Math.max(0, menu.offsetLeft - sub.offsetWidth);
    }
    let top = menu.offsetTop + (this._copyItemEl?.offsetTop ?? 0);
    if (top + sub.offsetHeight > size[1]) {
      top = Math.max(0, size[1] - sub.offsetHeight - 2);
    }
    sub.style.left = `${left}px`;
    sub.style.top = `${top}px`;
  }

  _onCopySubMenuKeyDown(e) {
    const menu = this._copySubMenu;
    switch (e.code) {
      case 'Escape':
      case 'ArrowLeft':
        e.preventDefault();
        e.stopPropagation();
        this._hideCopySubMenu();
        this._focusItem(this._items.findIndex((it) => it.id === 'copy'));
        return;
      case 'ArrowDown':
        e.preventDefault();
        e.stopPropagation();
        this._moveLayerFocus(menu, 1);
        return;
      case 'ArrowUp':
        e.preventDefault();
        e.stopPropagation();
        this._moveLayerFocus(menu, -1);
        return;
      case 'Tab':
        e.preventDefault();
        e.stopPropagation();
        this._moveLayerFocus(menu, e.shiftKey ? -1 : 1);
        return;
      case 'Home':
        e.preventDefault();
        e.stopPropagation();
        this._focusLayerItem(menu, 0);
        return;
      case 'End':
        e.preventDefault();
        e.stopPropagation();
        this._focusLayerItem(menu, menu._items.length - 1);
        return;
      case 'Enter':
      case 'Space':
        e.preventDefault();
        e.stopPropagation();
        menu._items[menu._activeIndex ?? 0].el.click();
        return;
    }
  }

  // Copy the whole viewer markup (the OL analog of MapML.js `_copyMapML`; the
  // custom element's light DOM is already free of the internal map container).
  _copyMapML() {
    this._copyData(this._viewer.outerHTML);
  }

  // Copy the current view extent as a <map-meta name="extent"> in the default
  // extent CS. Ported from MapML.js ContextMenu.js `_copyExtent`.
  _copyExtent() {
    const coord = (this.defExtCS || 'pcrs').toLowerCase();
    const extent = this._viewer.extent;
    if (!extent) return;
    const tL = extent.topLeft[coord];
    const bR = extent.bottomRight[coord];
    if (!tL || !bR) return;
    let data = '';
    if (coord === 'pcrs') {
      data = `<map-meta name="extent" content="top-left-easting=${Math.round(
        tL.horizontal
      )}, top-left-northing=${Math.round(
        tL.vertical
      )}, bottom-right-easting=${Math.round(
        bR.horizontal
      )}, bottom-right-northing=${Math.round(bR.vertical)}"></map-meta>`;
    } else if (coord === 'gcrs') {
      data = `<map-meta name="extent" content="top-left-longitude=${tL.horizontal}, top-left-latitude=${tL.vertical}, bottom-right-longitude=${bR.horizontal}, bottom-right-latitude=${bR.vertical}"></map-meta>`;
    } else if (coord === 'tcrs') {
      data = `<map-meta name="extent" content="top-left-x=${
        tL[0].horizontal
      }, top-left-y=${tL[0].vertical}, bottom-right-x=${
        bR[bR.length - 1].horizontal
      }, bottom-right-y=${bR[bR.length - 1].vertical}"></map-meta>`;
    } else if (coord === 'tilematrix') {
      data = `<map-meta name="extent" content="top-left-column=${
        tL[0].horizontal
      }, top-left-row=${tL[0].vertical}, bottom-right-column=${
        bR[bR.length - 1].horizontal
      }, bottom-right-row=${bR[bR.length - 1].vertical}"></map-meta>`;
    } else {
      return;
    }
    this._copyData(data);
  }

  // Copy the clicked location as a <map-feature> in the default location CS.
  // Ported from MapML.js ContextMenu.js `_copyLocation` + `_copy*` variants.
  _copyLocation() {
    const cs = (this.defLocCS || 'gcrs').toLowerCase();
    this._copyLocationFeature(cs);
  }

  _copyLocationFeature(kind) {
    const viewer = this._viewer;
    const projection = viewer.projection;
    const crs = window.M?.[projection];
    const view = this._map.getView();
    const coordinate = this._clickCoordinate ?? view.getCenter();
    if (!crs || !coordinate) return;
    const [x, y] = coordinate;
    const formatted = Util._convertAndFormatPCRS(
      bounds([x, y], [x, y]),
      crs,
      projection
    );
    const tl = formatted.topLeft;
    const resolutions = crs.options.resolutions.length;
    const zIndex = Math.max(
      0,
      Math.min(resolutions - 1, Math.round(view.getZoom()))
    );
    const tileSize = crs.options.crs.tile.bounds.max.x;
    const lng = tl.gcrs.horizontal.toFixed(6);
    const lat = tl.gcrs.vertical.toFixed(6);
    const gcrsCoords = `${lng} ${lat}`;

    let cs = 'gcrs';
    let label;
    let coords = gcrsCoords;
    let div = gcrsCoords;
    switch (kind) {
      case 'pcrs': {
        cs = 'pcrs';
        label = `Copied ${projection} pcrs location`;
        coords = `${Math.round(tl.pcrs.horizontal)} ${Math.round(
          tl.pcrs.vertical
        )}`;
        div = coords;
        break;
      }
      case 'tcrs': {
        cs = 'tcrs';
        label = `Copied ${projection} tcrs location`;
        const t = tl.tcrs[zIndex];
        coords = `${t.horizontal.toFixed(0)} ${t.vertical.toFixed(0)}`;
        div = coords;
        break;
      }
      case 'tilematrix': {
        label = `Copied ${projection} tilematrix location (not implemented yet)`;
        const t = tl.tcrs[zIndex];
        div = `${Math.trunc(t.horizontal / tileSize)} ${Math.trunc(
          t.vertical / tileSize
        )}`;
        break;
      }
      case 'tile': {
        label = `Copied ${projection} tile location (not implemented yet)`;
        const t = tl.tcrs[zIndex];
        let tx = Math.trunc(t.horizontal % tileSize);
        let ty = Math.trunc(t.vertical % tileSize);
        if (tx < 0) tx += tileSize;
        if (ty < 0) ty += tileSize;
        div = `${tx} ${ty}`;
        break;
      }
      case 'map': {
        label = `Copied ${projection} map location (not implemented yet)`;
        const px = this._clickPixel ?? [0, 0];
        div = `${Math.trunc(px[0])} ${Math.trunc(px[1])}`;
        break;
      }
      case 'gcrs':
      default:
        label = `Copied ${projection} gcrs location`;
    }

    const markup = `<map-feature zoom="${viewer.zoom}">
        <map-featurecaption>${label}</map-featurecaption>
        <map-properties>
            <h2>${label}</h2>
            <div style="text-align:center">${div}</div>
        </map-properties>
        <map-geometry cs="${cs}">
          <map-point>
            <map-coordinates>${coords}</map-coordinates>
          </map-point>
        </map-geometry>
      </map-feature>`;
    this._copyData(markup);
  }

  // Write text to the clipboard. Ported from MapML.js ContextMenu.js `_copyData`
  // (execCommand there; the async Clipboard API here).
  _copyData(data) {
    navigator.clipboard?.writeText(data);
  }

  // Build the two-item layer and extent context menus (Zoom / Copy). Ported
  // from MapML.js ContextMenu.js `_layerItems` / `_extentLayerItems`; the menus
  // are siblings of the map menu inside .mapml-container. Opened from the layer
  // control via `openLayerMenu`.
  _buildLayerMenus() {
    const L = this._locale;
    this._layerMenuEl = this._makeLayerMenu('mapml-layer-menu', [
      {
        id: 'zoom-layer',
        label: L.lmZoomToLayer,
        kbd: 'Z',
        run: () => this._layerClicked?.layer?.zoomTo()
      },
      {
        id: 'copy-layer',
        label: L.lmCopyLayer,
        kbd: 'L',
        run: () => this._copyElementMarkup(this._layerClicked?.layer)
      }
    ]);
    this._extentMenuEl = this._makeLayerMenu('mapml-extent-menu', [
      {
        id: 'zoom-extent',
        label: L.lmZoomToExtent,
        kbd: 'Z',
        run: () => this._layerClicked?.extent?.zoomTo()
      },
      {
        id: 'copy-extent',
        label: L.lmCopyExtent,
        kbd: 'L',
        run: () => this._copyElementMarkup(this._layerClicked?.extent)
      }
    ]);
  }

  _makeLayerMenu(className, defs) {
    const menu = document.createElement('div');
    menu.className = `mapml-contextmenu ${className}`;
    menu.setAttribute('role', 'menu');
    menu.setAttribute('tabindex', '-1');
    menu.hidden = true;
    const items = [];
    for (const def of defs) {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'mapml-contextmenu-item';
      btn.setAttribute('role', 'menuitem');
      btn.dataset.id = def.id;
      btn.tabIndex = -1;
      btn.innerHTML = `<span>${def.label}</span><kbd>${def.kbd}</kbd>`;
      btn.addEventListener('click', () => {
        def.run();
        this._closeLayerMenu();
      });
      menu.appendChild(btn);
      items.push({ el: btn, run: def.run });
    }
    menu._items = items;
    menu._activeIndex = 0;
    menu.addEventListener('keydown', (e) => this._onLayerMenuKeyDown(e, menu));
    this._viewer._container.appendChild(menu);
    return menu;
  }

  // Open the layer or extent context menu for a layer-control fieldset.
  // `kind` is 'layer' or 'extent'; `element` is the <map-layer>/<map-extent>;
  // `pixel` is [x, y] relative to .mapml-container; `returnFocus` is the item
  // to refocus when the menu closes.
  openLayerMenu(kind, element, pixel, returnFocus) {
    // Only one menu at a time.
    this.close();
    this._closeLayerMenu();
    this._layerClicked =
      kind === 'extent' ? { extent: element } : { layer: element };
    const menu = kind === 'extent' ? this._extentMenuEl : this._layerMenuEl;
    this._layerReturnFocus = returnFocus ?? null;
    menu.hidden = false;
    this._openLayerMenuEl = menu;
    // Suspend OpenLayers' arrow-key pan/zoom so menu navigation keys don't also
    // move the map (focus is inside .mapml-container, whose keydown OL listens
    // to).
    this._suspendMapKeyboard();
    this._positionMenu(menu, pixel[0], pixel[1]);
    this._focusLayerItem(menu, 0);
  }

  get isLayerMenuOpen() {
    return Boolean(this._openLayerMenuEl);
  }

  _positionMenu(menu, x, y) {
    const size = this._map.getSize() ?? [0, 0];
    const maxX = Math.max(0, size[0] - menu.offsetWidth - 2);
    const maxY = Math.max(0, size[1] - menu.offsetHeight - 2);
    menu.style.left = `${Math.min(Math.max(0, x), maxX)}px`;
    menu.style.top = `${Math.min(Math.max(0, y), maxY)}px`;
  }

  _closeLayerMenu() {
    const menu = this._openLayerMenuEl;
    if (!menu) return;
    menu.hidden = true;
    this._openLayerMenuEl = null;
    this._restoreMapKeyboard();
    const returnFocus = this._layerReturnFocus;
    this._layerReturnFocus = null;
    returnFocus?.focus?.();
  }

  _focusLayerItem(menu, i) {
    menu._items.forEach((it, j) => {
      it.el.tabIndex = j === i ? 0 : -1;
    });
    menu._activeIndex = i;
    menu._items[i].el.focus();
  }

  _moveLayerFocus(menu, delta) {
    const n = menu._items.length;
    const i = ((menu._activeIndex ?? 0) + delta + n) % n;
    this._focusLayerItem(menu, i);
  }

  _onLayerMenuKeyDown(e, menu) {
    switch (e.code) {
      case 'Escape':
      case 'ContextMenu':
        e.preventDefault();
        this._closeLayerMenu();
        return;
      case 'ArrowDown':
        e.preventDefault();
        this._moveLayerFocus(menu, 1);
        return;
      case 'ArrowUp':
        e.preventDefault();
        this._moveLayerFocus(menu, -1);
        return;
      case 'Tab':
        e.preventDefault();
        this._moveLayerFocus(menu, e.shiftKey ? -1 : 1);
        return;
      case 'Home':
        e.preventDefault();
        this._focusLayerItem(menu, 0);
        return;
      case 'End':
        e.preventDefault();
        this._focusLayerItem(menu, menu._items.length - 1);
        return;
      case 'Enter':
      case 'Space':
        e.preventDefault();
        menu._items[menu._activeIndex ?? 0].el.click();
        return;
      // Single-letter shortcuts mirror MapML.js: Z = Zoom, L = Copy.
      case 'KeyZ':
        e.preventDefault();
        menu._items[0].run();
        this._closeLayerMenu();
        return;
      case 'KeyL':
        e.preventDefault();
        menu._items[1].run();
        this._closeLayerMenu();
        return;
    }
  }

  // Copy an element's serialized markup to the clipboard. Ported from MapML.js
  // ContextMenu.js `_copyLayer` / `_copyMapExtent` (execCommand there; the
  // async Clipboard API here, matching the paste path).
  _copyElementMarkup(element) {
    if (!element) return;
    const markup =
      typeof element.getOuterHTML === 'function'
        ? element.getOuterHTML()
        : element.outerHTML;
    this._copyData(markup);
  }

  get isOpen() {
    return !this._menu.hidden;
  }

  _openAt(x, y, byKeyboard) {
    this._updateEnabledState();
    this._wasOpenedByKeyboard = byKeyboard;
    this._menu.hidden = false;
    // Suspend OpenLayers' arrow-key pan/zoom so navigation keys reach the menu
    // rather than moving the map (they act on any non-editable focus).
    this._suspendMapKeyboard();

    const size = this._map.getSize() ?? [0, 0];
    const maxX = Math.max(0, size[0] - this._menu.offsetWidth - 2);
    const maxY = Math.max(0, size[1] - this._menu.offsetHeight - 2);
    this._menu.style.left = `${Math.min(Math.max(0, x), maxX)}px`;
    this._menu.style.top = `${Math.min(Math.max(0, y), maxY)}px`;

    if (byKeyboard) {
      const first = this._firstEnabledIndex();
      if (first >= 0) this._focusItem(first);
      else this._menu.focus();
    }
  }

  close() {
    if (this._menu.hidden) return;
    this._hideCopySubMenu();
    this._menu.hidden = true;
    this._restoreMapKeyboard();
    if (this._wasOpenedByKeyboard) {
      this._viewer.focus?.();
    }
    this._wasOpenedByKeyboard = false;
  }

  _suspendMapKeyboard() {
    this._suspendedInteractions = [];
    this._map.getInteractions().forEach((interaction) => {
      if (interaction instanceof MapKeyboard && interaction.getActive()) {
        interaction.setActive(false);
        this._suspendedInteractions.push(interaction);
      }
    });
  }

  _restoreMapKeyboard() {
    this._suspendedInteractions?.forEach((interaction) =>
      interaction.setActive(true)
    );
    this._suspendedInteractions = [];
  }

  _onMapContextMenu(evt) {
    evt.originalEvent?.preventDefault();
    const [x, y] = evt.pixel;
    this._clickCoordinate = evt.coordinate;
    this._clickPixel = evt.pixel;
    this._openAt(x, y, false);
  }

  _onDocumentMouseDown(e) {
    const path = e.composedPath();
    if (this._openLayerMenuEl && !path.includes(this._openLayerMenuEl)) {
      this._closeLayerMenu();
    }
    if (this._menu.hidden) return;
    if (path.includes(this._menu) || path.includes(this._copySubMenu)) return;
    this.close();
  }

  _onDocumentKeyDown(e) {
    // A layer/extent menu handles its own keys via its keydown listener.
    if (this._openLayerMenuEl) return;
    const path = e.composedPath();
    if (!path.includes(this._viewer) && this._menu.hidden) return;

    if (!this._menu.hidden && e.key === 'Escape') {
      e.preventDefault();
      this.close();
      return;
    }
    if (
      !this._menu.hidden &&
      (e.key === 'ContextMenu' || (e.shiftKey && e.key === 'F10'))
    ) {
      e.preventDefault();
      this.close();
      return;
    }

    // Menu-open single-letter shortcut for a mouse-opened menu (focus
    // still on the canvas). When focus is inside the menu, _onMenuKeyDown
    // handles it first and preventDefault marks the event consumed.
    if (!this._menu.hidden && !e.defaultPrevented) {
      if (this._handleMenuLetterShortcut(e)) return;
    }

    if (this._menu.hidden) {
      this._handleMapWideShortcut(e);
    }
  }

  _handleMenuLetterShortcut(e) {
    if (this._menu.hidden) return false;
    if (e.ctrlKey || e.metaKey || e.altKey) return false;
    if (e.code === 'KeyC') {
      e.preventDefault();
      this._showCopySubMenu();
      this._focusLayerItem(this._copySubMenu, 0);
      return true;
    }
    if (e.code === 'KeyM') {
      e.preventDefault();
      this._copyMapML();
      this.close();
      return true;
    }
    if (e.code === 'KeyF') {
      e.preventDefault();
      this._viewer.toggleFullScreen();
      this.close();
      return true;
    }
    if (e.code === 'KeyT') {
      e.preventDefault();
      this._viewer.toggleControls();
      this.close();
      return true;
    }
    if (e.code === 'KeyP') {
      e.preventDefault();
      this._paste();
      this.close();
      return true;
    }
    if (e.code === 'KeyD') {
      e.preventDefault();
      this._viewer.toggleDebug();
      this.close();
      return true;
    }
    if (e.code === 'KeyV') {
      e.preventDefault();
      this._viewer.viewSource();
      this.close();
      return true;
    }
    return false;
  }

  _handleMapWideShortcut(e) {
    if (
      this._menu.hidden &&
      (e.key === 'ContextMenu' || (e.shiftKey && e.key === 'F10'))
    ) {
      e.preventDefault();
      const size = this._map.getSize() ?? [0, 0];
      this._clickCoordinate = this._map.getView().getCenter();
      this._clickPixel = [size[0] / 2, size[1] / 2];
      this._openAt(size[0] / 2, size[1] / 2, true);
      return;
    }
    if (e.altKey && !e.ctrlKey && !e.metaKey && !e.shiftKey) {
      if (e.code === 'ArrowLeft') {
        e.preventDefault();
        this._viewer.back();
        return;
      }
      if (e.code === 'ArrowRight') {
        e.preventDefault();
        this._viewer.forward();
        return;
      }
    }
    if (
      (e.ctrlKey || e.metaKey) &&
      e.code === 'KeyR' &&
      !e.altKey &&
      !e.shiftKey
    ) {
      // Only intercept the browser reload when there is map history to
      // reset to; at the initial location let the browser reload the page.
      if (this._historyState().canReload) {
        e.preventDefault();
        this._viewer.reload();
      }
    }
  }

  _onMenuKeyDown(e) {
    switch (e.code) {
      case 'Escape':
        e.preventDefault();
        this.close();
        return;
      case 'ArrowDown':
        e.preventDefault();
        this._moveFocus(1);
        return;
      case 'ArrowUp':
        e.preventDefault();
        this._moveFocus(-1);
        return;
      case 'Tab':
        e.preventDefault();
        this._moveFocus(e.shiftKey ? -1 : 1);
        return;
      case 'Home':
        e.preventDefault();
        this._focusItem(this._firstEnabledIndex());
        return;
      case 'End':
        e.preventDefault();
        this._focusItem(this._lastEnabledIndex());
        return;
      case 'ArrowRight':
        // Open the Copy submenu when the "Copy" item is focused.
        if (this._items[this._activeIndex]?.id === 'copy') {
          e.preventDefault();
          this._showCopySubMenu();
          this._focusLayerItem(this._copySubMenu, 0);
        }
        return;
      case 'Enter':
      case 'Space': {
        const active = this._items[this._activeIndex];
        if (active?.id === 'copy') {
          e.preventDefault();
          this._showCopySubMenu();
          this._focusLayerItem(this._copySubMenu, 0);
          return;
        }
        if (active && !active.el.disabled) {
          e.preventDefault();
          active.el.click();
        }
        return;
      }
      case 'KeyC':
      case 'KeyM':
      case 'KeyF':
      case 'KeyT':
      case 'KeyP':
      case 'KeyD':
      case 'KeyV':
        this._handleMenuLetterShortcut(e);
        return;
    }
  }

  _moveFocus(delta) {
    const n = this._items.length;
    if (n === 0) return;
    // Moving within the main menu dismisses an open Copy submenu.
    this._hideCopySubMenu();
    let i = this._activeIndex;
    for (let step = 0; step < n; step++) {
      i = (i + delta + n) % n;
      if (!this._items[i].el.disabled) {
        this._focusItem(i);
        return;
      }
    }
  }

  _firstEnabledIndex() {
    return this._items.findIndex((it) => !it.el.disabled);
  }

  _lastEnabledIndex() {
    for (let i = this._items.length - 1; i >= 0; i--) {
      if (!this._items[i].el.disabled) return i;
    }
    return -1;
  }

  _focusItem(i) {
    if (i < 0) return;
    for (let j = 0; j < this._items.length; j++) {
      this._items[j].el.tabIndex = j === i ? 0 : -1;
    }
    this._activeIndex = i;
    this._items[i].el.focus();
  }
}
