/**
 * `<map-extent>` — groups the `<map-input>` variables and the `<map-link>` that
 * references them. Named `HTMLExtentElement` to match MapML.js, where each
 * `<map-extent>` *is* a Leaflet `LayerGroup`; here it owns a nested
 * `ol/layer/Group` pushed into its parent `<map-layer>`'s group in DOM order.
 *
 * `checked` drives the extent group's visibility; `units` names the tiled CRS.
 * The layer-control sub-fieldset is built by `getLayerControlHTML()` (ported
 * from MapML.js's createLayerControlForExtent.js).
 */
/* global M */
import LayerGroup from 'ol/layer/Group.js';
import { calculatePosition } from './mapml/elementSupport/layers/calculatePosition.js';
import { createLayerControlForExtent } from './mapml/elementSupport/extents/createLayerControlForExtent.js';
import { Util } from './mapml/utils/Util.js';
import { toBounds as bounds } from './mapml/geometry/Bounds.js';

export class HTMLExtentElement extends HTMLElement {
  static get observedAttributes() {
    return ['units', 'checked', 'hidden'];
  }

  constructor() {
    super();
    this._settingsExpanded = false;
  }

  get units() {
    return this.getAttribute('units') || '';
  }

  // Extent name shown in the layer control (falls back to the projection name).
  get label() {
    return this.getAttribute('label') || this.units;
  }

  get checked() {
    return this.hasAttribute('checked');
  }
  set checked(value) {
    if (value) {
      this.setAttribute('checked', '');
    } else {
      this.removeAttribute('checked');
    }
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (oldValue === newValue) {
      return;
    }
    if (name === 'checked') {
      this._extentGroup?.setVisible(this.checked);
    } else if (name === 'hidden') {
      // `hidden` toggles this extent's presence as a sublayer in the layer
      // control; rebuild it. Ported from MapML.js map-extent.js.
      this._viewer?.dispatchEvent(new CustomEvent('mapml:layerschanged'));
    }
  }

  // Reflect opacity to the extent group (called by the opacity slider).
  setOpacity(value) {
    this._extentGroup?.setOpacity(Number(value));
  }

  // Fit the view to this extent's bounds. Ported from MapML.js map-extent.js
  // `zoomTo`; used by the layer-control context menu ("Zoom To Extent").
  zoomTo() {
    this._calculateBounds();
    const map = this._viewer?.map;
    const b = this.getLayerGroup()?.bounds;
    if (!b || !map) return;
    map.getView().fit([b.min.x, b.min.y, b.max.x, b.max.y], {
      size: map.getSize()
    });
    this._viewer._updateMapCenter();
  }

  // Serialize this extent to markup with template `href`/`tref` URLs resolved
  // to absolute so the copied text works when pasted elsewhere. Ported from
  // MapML.js map-extent.js `getOuterHTML` (used by the "Copy Extent" menu item).
  getOuterHTML() {
    const tempElement = this.cloneNode(true);
    if (this.querySelector('map-link')) {
      tempElement.querySelectorAll('map-link').forEach((mapLink) => {
        const base = this.baseURI || document.baseURI;
        if (mapLink.hasAttribute('href')) {
          mapLink.setAttribute(
            'href',
            decodeURI(new URL(mapLink.getAttribute('href'), base).href)
          );
        } else if (mapLink.hasAttribute('tref')) {
          mapLink.setAttribute(
            'tref',
            decodeURI(new URL(mapLink.getAttribute('tref'), base).href)
          );
        }
      });
    }
    return tempElement.outerHTML;
  }

  // The extent's envelope (pcrs/gcrs/tcrs/tilematrix corners + zoom), ported
  // from MapML.js map-extent.js `get extent`. MapML.js stores the derived
  // bounds on the Leaflet `_extentLayer` LayerGroup; the OL analog is this
  // extent's `ol/layer/Group` (`_extentGroup`), created via `getLayerGroup()`.
  get extent() {
    const getExtent = (extent) => {
      return Object.assign(
        Util._convertAndFormatPCRS(
          extent._extentGroup.bounds,
          M[extent.units],
          extent.units
        ),
        { zoom: extent._extentGroup.zoomBounds }
      );
    };
    const getCalculatedExtent = (extent) => {
      extent._calculateBounds();
      return getExtent(extent);
    };
    const extentGroup = this.getLayerGroup();
    return extentGroup.bounds ? getExtent(this) : getCalculatedExtent(this);
  }

  // DOM-order z-index within the parent layer group (each extent is unique).
  get position() {
    return calculatePosition(this);
  }

  async connectedCallback() {
    this._viewer = Util.getClosest(this, 'mapml-viewer');
    if (!this._viewer) {
      return;
    }
    await this._viewer.whenReady();
    if (!this.isConnected) {
      return;
    }
    this.getLayerGroup();
    // Rebuild the layer control so this extent appears as a sublayer.
    this._viewer.dispatchEvent(new CustomEvent('mapml:layerschanged'));
  }

  disconnectedCallback() {
    if (this._extentGroup && this._parentCollection) {
      this._parentCollection.remove(this._extentGroup);
    }
    this._extentGroup = null;
    this._parentCollection = null;
    this._viewer?.dispatchEvent(new CustomEvent('mapml:layerschanged'));
  }

  // Live list of the child <map-input> elements declaring tref variables.
  getInputs() {
    return Array.from(this.querySelectorAll(':scope > map-input'));
  }

  // Resolve a <map-meta name=extent|zoom|cs> for this extent: its own child
  // first, then the containing <map-layer>'s. Ported from MapML.js
  // map-extent.js getMeta (local-content branch; the map-layer[src] shadowRoot
  // branch lands with remote layers).
  getMeta(metaName) {
    let name = metaName.toLowerCase();
    if (name !== 'extent' && name !== 'zoom' && name !== 'cs') return;
    const layerEl = Util.getClosest(this, 'map-layer');
    // Remote (<map-layer src>) meta live in the layer's shadow root; query it
    // with the `:host >` pseudo. Ported from MapML.js map-extent.js getMeta.
    return layerEl?.src
      ? this.querySelector(`:scope > map-meta[name=${name}]`) ||
          layerEl.shadowRoot.querySelector(`:host > map-meta[name=${name}]`)
      : this.querySelector(`:scope > map-meta[name=${name}]`) ||
          layerEl?.querySelector(`:scope > map-meta[name=${name}]`);
  }

  // Derive the extent's PCRS bounds + zoomBounds by unioning the child
  // <map-link> template bounds/zoom over the extent's own <map-meta>. Ported
  // from MapML.js map-extent.js _calculateBounds. As in MapML.js — where the
  // result lives on the Leaflet `_extentLayer` LayerGroup — the OL port stores
  // it on `_extentGroup`, this extent's `ol/layer/Group` (its OL analog), which
  // the parent <map-layer> union reads. The dead top-of-function zoom
  // accumulators from the source (shadowed by the loop's own locals) are omitted.
  _calculateBounds() {
    const extentLayer = this.getLayerGroup();
    delete extentLayer.bounds;
    delete extentLayer.zoomBounds;
    let templates = this.querySelectorAll(
      'map-link[rel=image]:not([disabled]),map-link[rel=tile]:not([disabled]),map-link[rel=features]:not([disabled]),map-link[rel=query]:not([disabled])'
    );

    // initialize bounds from this.scope > map-meta
    let bnds = this.querySelector(':scope > map-meta[name=extent][content]')
      ? Util.getBoundsFromMeta(this)
      : undefined;

    // initialize zoom bounds from this.scope > map-meta
    let zoomBounds = this.querySelector(':scope > map-meta[name=zoom][content]')
      ? Util.getZoomBoundsFromMeta(this)
      : undefined;

    // bounds should be able to be calculated unconditionally, not depend on map-extent.checked
    for (let j = 0; j < templates.length; j++) {
      const templateZoomBounds = templates[j].getZoomBounds(),
        templateBounds = templates[j].getBounds();
      let zoomMax =
          zoomBounds && Object.hasOwn(zoomBounds, 'maxZoom')
            ? zoomBounds.maxZoom
            : -Infinity,
        zoomMin =
          zoomBounds && Object.hasOwn(zoomBounds, 'minZoom')
            ? zoomBounds.minZoom
            : Infinity,
        minNativeZoom =
          zoomBounds && Object.hasOwn(zoomBounds, 'minNativeZoom')
            ? zoomBounds.minNativeZoom
            : Infinity,
        maxNativeZoom =
          zoomBounds && Object.hasOwn(zoomBounds, 'maxNativeZoom')
            ? zoomBounds.maxNativeZoom
            : -Infinity;
      if (!zoomBounds) {
        zoomBounds = Object.assign({}, templateZoomBounds);
      } else {
        zoomMax = Math.max(zoomMax, templateZoomBounds.maxZoom);
        zoomMin = Math.min(zoomMin, templateZoomBounds.minZoom);
        maxNativeZoom = Math.max(
          maxNativeZoom,
          templateZoomBounds.maxNativeZoom
        );
        minNativeZoom = Math.min(
          minNativeZoom,
          templateZoomBounds.minNativeZoom
        );
        zoomBounds.minZoom = zoomMin;
        zoomBounds.maxZoom = zoomMax;
        zoomBounds.minNativeZoom = minNativeZoom;
        zoomBounds.maxNativeZoom = maxNativeZoom;
      }
      if (!bnds) {
        bnds = bounds(templateBounds.min, templateBounds.max);
      } else {
        bnds.extend(templateBounds);
      }
    }
    if (bnds) {
      extentLayer.bounds = bnds;
    } else {
      extentLayer.bounds = bounds(
        M[this.units].options.bounds.min,
        M[this.units].options.bounds.max
      );
    }
    if (!zoomBounds) zoomBounds = {};
    if (!Object.hasOwn(zoomBounds, 'minZoom')) {
      zoomBounds.minZoom = 0;
    }
    if (!Object.hasOwn(zoomBounds, 'maxZoom')) {
      zoomBounds.maxZoom = M[this.units].options.resolutions.length - 1;
    }
    if (
      !Object.hasOwn(zoomBounds, 'minNativeZoom') ||
      zoomBounds.minNativeZoom === Infinity
    ) {
      zoomBounds.minNativeZoom = zoomBounds.minZoom;
    }
    if (
      !Object.hasOwn(zoomBounds, 'maxNativeZoom') ||
      zoomBounds.maxNativeZoom === -Infinity
    ) {
      zoomBounds.maxNativeZoom = zoomBounds.maxZoom;
    }
    extentLayer.zoomBounds = zoomBounds;
  }

  // Whether this extent's tiled CRS matches the map's projection. Ported from
  // MapML.js map-extent.js `_projectionMatch`.
  _projectionMatch() {
    return (
      this.units.toUpperCase() === (this._viewer?.projection || '').toUpperCase()
    );
  }

  // Resolve once the child template links have built their layers. The OL
  // map-link builds asynchronously in its own connectedCallback; there is no
  // per-link ready promise yet, so this resolves immediately and callers rely
  // on the map `moveend` re-validation to settle transient states. Kept as a
  // named method to mirror MapML.js map-extent.js `whenLinksReady`.
  whenLinksReady() {
    return Promise.resolve();
  }

  // Disable this extent when its CRS doesn't match the map projection or none
  // of its template links are visible; enable it otherwise. Sets/removes the
  // `disabled` attribute (asserted by tests) and italicizes the layer-control
  // sub-fieldset. Ported from MapML.js map-extent.js `_validateDisabled`.
  _validateDisabled() {
    if (!this._extentGroup) return this.disabled;
    const templates = this.querySelectorAll(
      'map-link[rel=image],map-link[rel=tile],map-link[rel=features],map-link[rel=query]'
    );
    const noTemplateVisible = () => {
      let total = templates.length,
        disabledCount = 0;
      for (let j = 0; j < total; j++) {
        if (!templates[j].isVisible()) disabledCount++;
      }
      return disabledCount === total;
    };
    if (!this._projectionMatch() || noTemplateVisible()) {
      this.setAttribute('disabled', '');
      this.disabled = true;
    } else {
      this.removeAttribute('disabled');
      this.disabled = false;
    }
    this.toggleLayerControlDisabled();
    return this.disabled;
  }

  // Disable/italicize the extent's layer-control sub-fieldset based on
  // `this.disabled`. Ported from MapML.js map-extent.js
  // `toggleLayerControlDisabled`; guards each reference because the OL layer
  // control is rebuilt on `mapml:layerschanged` and may not have stamped them.
  toggleLayerControlDisabled() {
    const input = this._layerControlCheckbox,
      label = this._layerControlLabel,
      opacityControl = this._opacityControl,
      opacitySlider = this._opacitySlider,
      selectDetails = this._selectdetails;
    const fs = this.disabled ? 'italic' : 'normal';
    if (input) input.disabled = this.disabled;
    if (opacitySlider) opacitySlider.disabled = this.disabled;
    if (label) label.style.fontStyle = fs;
    if (opacityControl) opacityControl.style.fontStyle = fs;
    if (selectDetails) {
      selectDetails.forEach((i) => {
        i.querySelectorAll('select').forEach((j) => {
          j.disabled = this.disabled;
          j.style.fontStyle = fs;
        });
        i.style.fontStyle = fs;
      });
    }
  }

  // Lazily create the extent group and nest it in the parent layer's group
  // (or the map root when used directly under the viewer).
  getLayerGroup() {
    if (this._extentGroup) {
      return this._extentGroup;
    }
    this._viewer = this._viewer || Util.getClosest(this, 'mapml-viewer');
    const layerEl = Util.getClosest(this, 'map-layer');
    this._parentCollection = layerEl
      ? layerEl.getLayerGroup().getLayers()
      : this._viewer.map.getLayers();
    this._extentGroup = new LayerGroup({ layers: [], visible: this.checked });
    // Render order is driven by zIndex (DOM position), mirroring MapML.js's
    // `zIndex: this.position` / `_extentLayer.setZIndex(this.position)`.
    this._extentGroup.setZIndex(this.position);
    this._parentCollection.push(this._extentGroup);
    return this._extentGroup;
  }

  // Build the per-extent sub-fieldset for the layer control. Delegates to the
  // ported createLayerControlForExtent.js builder (kept standalone to diff 1:1
  // against MapML.js).
  getLayerControlHTML(locale) {
    return createLayerControlForExtent(this, locale);
  }

  // Re-apply this extent's templated links (tile/image/features) so a changed
  // template variable takes effect. Ported from MapML.js map-select.js, where
  // changing a `<map-select>` calls `this.parentElement._extentLayer.redraw()`.
  refresh() {
    this.querySelectorAll(
      ':scope > map-link[rel=tile],:scope > map-link[rel=image],:scope > map-link[rel=features]'
    ).forEach((link) => link.refresh?.());
  }

  // Resolve once this extent's OL group exists (its bounds/templates are then
  // computed). Ported from MapML.js map-extent.js whenReady (which polls
  // `_extentLayer`); the OL analog is `_extentGroup`.
  whenReady() {
    return new Promise((resolve, reject) => {
      let interval, failureTimer;
      if (this._extentGroup) {
        resolve();
      } else {
        interval = setInterval(testForExtent, 300, this);
        failureTimer = setTimeout(extentNotDefined, 10000);
      }
      function testForExtent(extentElement) {
        if (extentElement._extentGroup) {
          clearInterval(interval);
          clearTimeout(failureTimer);
          resolve();
        } else if (!extentElement.isConnected) {
          clearInterval(interval);
          clearTimeout(failureTimer);
          reject('map-extent was disconnected while waiting to be ready');
        }
      }
      function extentNotDefined() {
        clearInterval(interval);
        clearTimeout(failureTimer);
        reject('Timeout reached waiting for extent to be ready');
      }
    });
  }
}
