// Styles for the debug overlay panel (the coordinate read-out table + banner),
// injected into the viewer shadow root. Ported 1:1 from MapML.js mapml.css
// `.mapml-debug*` rules. The tile grid + bounds vectors render on the OpenLayers
// canvas (unlike MapML.js's SVG/DOM), so only the HTML panel needs CSS here.
export const debugOverlayCss = /* css */ `
.mapml-debug {
  contain: content;
  max-height: 100%;
  max-width: 100%;
  border-radius: 4px;
  padding: 5px 10px;
  background-color: #fff;
  cursor: default;
  z-index: 1000;
  position: absolute;
  display: block;
  top: auto;
  right: 5px;
  bottom: 5px;
  left: 5px;
  width: fit-content;
  font: inherit;
}

.mapml-debug-banner {
  font-weight: bold;
  text-transform: uppercase;
  display: inline-block;
  text-align: left;
  text-align: inline-start;
  line-height: 2;
}

.mapml-debug-panel {
  font-family: monospace;
}

.mapml-debug-coordinates {
  padding-left: 4px;
  padding-right: 4px;
}

.mapml-debug,
.mapml-debug * {
  border-collapse: collapse;
  border-spacing: 0;
}

.mapml-debug-coordinates:empty {
  display: none;
}

.mapml-debug-coordinates > * {
  display: inline;
}
`;
