/**
 * Stylesheet for the native OpenLayers zoom control (`ol/control/Zoom`), the
 * top-left anchor of the control stack. Restyled from ol.css's small default
 * to match MapML.js/MapML-MapLibre: two abutting 40×40 buttons forming a
 * single bar with `+` / `−` glyphs at 30px, so it lines up with the reload and
 * fullscreen buttons stacked beneath it.
 */
export const zoomControlCss = /* css */ `
.ol-zoom {
  left: .5em;
  padding: 0;
  background: transparent;
  border-radius: 4px;
}

.ol-zoom button.ol-zoom-in,
.ol-zoom button.ol-zoom-out {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  margin: 0;
  padding: 0;
  font-family: 'Lucida Console', Monaco, monospace;
  font-size: 30px;
  font-weight: 700;
  line-height: 1;
  color: #333;
  background-color: #fff;
  border: 1px solid #e3e3e3;
}

.ol-zoom button.ol-zoom-in {
  border-radius: 4px 4px 0 0;
  border-bottom: none;
}
.ol-zoom button.ol-zoom-out {
  border-radius: 0 0 4px 4px;
}

/* Drop ol.css's gray hover/focus outline and draw the shared focus ring. */
.ol-zoom button:hover,
.ol-zoom button:focus:not(:focus-visible) {
  outline: none;
}
.ol-zoom button:focus-visible {
  outline: 2px solid var(--mapml-focus-ring-color);
  outline-offset: -2px;
}
`;
