/**
 * `LayerControl` — a genuine OpenLayers `Control` that renders the MapML.js
 * layer-toggle panel.
 *
 * Re-written against `ol/control/Control` (the previous MapML.js control
 * extended Leaflet's `Control.Layers`), but the per-item DOM and event
 * handling still come from MapML.js: each row is produced by
 * `MapLayer.getLayerControlHTML()` (which calls `MapExtent.getLayerControlHTML()`
 * for its sublayers), so the markup and class names match
 * `createLayerControlForLayer.js` / `createLayerControlForExtent.js`.
 *
 * The collapsed pill sizing/styling (40 x 40, stacked-layers icon) follows the
 * MapML-MapLibre port. Behaviour ported from MapML.js: hover/click to expand,
 * collapse on map movestart or an outside touch, and keyboard focus moves to
 * the first layer checkbox when expanded via the keyboard.
 */
import Control from 'ol/control/Control.js';

export class LayerControl extends Control {
  constructor(viewer) {
    const container = document.createElement('div');
    container.className = 'mapml-layer-control leaflet-control-layers';
    container.setAttribute('aria-haspopup', 'true');

    const toggle = document.createElement('a');
    toggle.className = 'leaflet-control-layers-toggle';
    toggle.href = '#';
    toggle.title = 'Layers';
    toggle.setAttribute('role', 'button');
    toggle.setAttribute('aria-label', 'Layers');

    const list = document.createElement('div');
    list.className = 'leaflet-control-layers-list';

    container.append(toggle, list);

    super({ element: container });

    this._viewer = viewer;
    this._container = container;
    this._toggle = toggle;
    this._list = list;

    this._expand = (event) => {
      event?.preventDefault();
      container.classList.add('leaflet-control-layers-expanded');
      // Keyboard-triggered "clicks" have detail === 0; move focus to the
      // first checkbox so the list is immediately navigable (MapML.js's
      // _focusFirstLayer).
      if (event instanceof MouseEvent && event.detail === 0) {
        setTimeout(() => this._focusFirstCheckbox(), 0);
      }
    };
    this._collapse = () => {
      // Keep the panel open while a layer/extent context menu is showing
      // (MapML.js collapse() returns early when a layer menu is visible).
      if (this._viewer._contextMenu?.isLayerMenuOpen) return;
      container.classList.remove('leaflet-control-layers-expanded');
    };

    toggle.addEventListener('click', this._expand);
    // On touch, expand() hides the toggle (display:none), so the browser
    // would retarget the synthetic click to whatever now sits under the
    // finger. preventDefault() on touchend suppresses those synthetic events.
    toggle.addEventListener(
      'touchend',
      (e) => {
        e.preventDefault();
        this._expand();
      },
      { passive: false }
    );
    container.addEventListener('mouseenter', this._expand);
    container.addEventListener('mouseleave', this._collapse);

    // Right-click / keyboard menu key on a layer or extent row opens the
    // layer-control context menu (Zoom To / Copy). Ported from MapML.js
    // LayerControl `_preventDefaultContextMenu` + ContextMenu `_show`.
    this._onContextMenu = (e) => this._openLayerContextMenu(e);
    list.addEventListener('contextmenu', this._onContextMenu);

    this._outsideTouch = (e) => {
      if (e.target instanceof Node && !container.contains(e.target)) {
        this._collapse();
      }
    };

    this._rebuild = () => this._rebuildList();
    viewer.addEventListener('mapml:layerschanged', this._rebuild);

    this._rebuildList();
  }

  // Called by map.addControl / removeControl; wire the map-scoped listeners.
  setMap(map) {
    const previous = this.getMap();
    if (previous) {
      previous.un('movestart', this._collapse);
      previous
        .getTargetElement()
        ?.removeEventListener('touchstart', this._outsideTouch);
    }
    super.setMap(map);
    if (map) {
      // Auto-collapse on pan/zoom and on any touch outside the control.
      map.on('movestart', this._collapse);
      map
        .getTargetElement()
        ?.addEventListener('touchstart', this._outsideTouch, { passive: true });
    }
  }

  _rebuildList() {
    const list = this._list;
    const container = this._container;
    if (!list || !container) {
      return;
    }
    list.replaceChildren();
    // `hidden` map-layers are hidden from the control (rendering follows
    // `checked` only), matching MapML.js. Skip not-yet-upgraded elements: the
    // control is built during map creation, before child <map-layer> elements
    // necessarily upgrade; each fires `mapml:layerschanged` on connect, which
    // rebuilds the list once they can produce their fieldset.
    const layers = this._viewer.layers.filter(
      (l) =>
        !l.hasAttribute('hidden') && typeof l.getLayerControlHTML === 'function'
    );
    if (layers.length === 0) {
      container.setAttribute('hidden', '');
      return;
    }
    container.removeAttribute('hidden');

    // Wrap in .leaflet-control-layers-overlays so MapML.js CSS that targets
    // descendants of that wrapper still applies.
    const overlays = document.createElement('fieldset');
    overlays.className = 'leaflet-control-layers-overlays';
    for (const layer of layers) {
      overlays.appendChild(layer.getLayerControlHTML(this._viewer.locale));
    }
    list.appendChild(overlays);
  }

  _focusFirstCheckbox() {
    this._list
      ?.querySelector(
        'fieldset.mapml-layer-item input.leaflet-control-layers-selector'
      )
      ?.focus();
  }

  // Open the Zoom/Copy context menu for the layer or extent row under the
  // pointer (or focused row for a keyboard menu key).
  _openLayerContextMenu(e) {
    const fieldset = e.target.closest(
      'fieldset.mapml-layer-item, fieldset.mapml-layer-extent'
    );
    const contextMenu = this._viewer._contextMenu;
    if (!fieldset || !fieldset._layerControlElement || !contextMenu) return;
    e.preventDefault();
    e.stopPropagation();
    const kind = fieldset.classList.contains('mapml-layer-extent')
      ? 'extent'
      : 'layer';
    const containerRect = this._viewer._container.getBoundingClientRect();
    // A keyboard menu key (Shift+F10 / ContextMenu) reports no usable pointer
    // coordinates; anchor the menu to the row instead.
    const byKeyboard = e.button < 0 || (e.clientX === 0 && e.clientY === 0);
    let pixel;
    if (byKeyboard) {
      const rect = fieldset.getBoundingClientRect();
      pixel = [
        rect.left - containerRect.left + 8,
        rect.top - containerRect.top + 8
      ];
    } else {
      pixel = [e.clientX - containerRect.left, e.clientY - containerRect.top];
    }
    const returnFocus = fieldset.querySelector(
      'input.leaflet-control-layers-selector'
    );
    contextMenu.openLayerMenu(
      kind,
      fieldset._layerControlElement,
      pixel,
      returnFocus
    );
  }
}
