/**
 * `ReloadButton` — top-left control that rewinds the map to the initial
 * history entry. Ported from MapML.js `src/mapml/control/ReloadButton.js`
 * (a Leaflet `Control`) to an OpenLayers `ol/control/Control`.
 *
 * Visual contract: a single 40×40 button bearing the `↺` glyph
 * (MapML.js's `&#x021BA;`). It is enabled only while the viewer's history
 * ring is not parked at its initial entry — i.e. `getState().canReload`,
 * which MapML.js expresses as `_history.length > 1` and disables together
 * with Back. Clicking calls the viewer's public `reload()`.
 */
import Control from 'ol/control/Control.js';

export class ReloadButton extends Control {
  constructor(viewer) {
    const container = document.createElement('div');
    container.className = 'mapml-reload-button ol-control';

    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'mapml-button';
    const title = viewer.locale.cmReload;
    button.title = title;
    button.setAttribute('aria-label', title);
    button.innerHTML =
      "<span class='mapml-reload-button-icon' aria-hidden='true'>&#x021BA;</span>";
    container.appendChild(button);

    super({ element: container });

    this._viewer = viewer;
    this._button = button;

    this._onClick = (event) => {
      event.stopPropagation();
      if (button.getAttribute('aria-disabled') === 'true') return;
      viewer.reload();
    };
    // MapML.js updates the disabled state on `moveend`; read the history
    // state (canReload) the same way the context menu does.
    this._onMoveEnd = () => this._updateDisabled();

    button.addEventListener('click', this._onClick);
    viewer._map.on('moveend', this._onMoveEnd);
    this._updateDisabled();
  }

  // Detach listeners when the control is uninstalled (controls/controlslist).
  destroy() {
    this._button.removeEventListener('click', this._onClick);
    this._viewer._map?.un('moveend', this._onMoveEnd);
  }

  _updateDisabled() {
    const enabled = this._viewer._history?.getState().canReload ?? false;
    this._button.disabled = !enabled;
    this._button.setAttribute('aria-disabled', enabled ? 'false' : 'true');
  }
}
