/**
 * `<map-meta>` — declares document/layer/extent metadata (projection, extent,
 * cs, zoom) as `name` + `content` attribute pairs. Renders nothing; the values
 * are read by `Util.getBoundsFromMeta` / `getZoomBoundsFromMeta` and by the
 * `<map-input>` min/max fallback chain.
 *
 * Ported from MapML.js `src/map-meta.js`. Named `HTMLMapMetaElement` to match
 * the OpenLayers port's `HTMLMap*Element` convention (MapML.js calls the class
 * `HTMLMetaElement`); registration is centralized in index.js rather than the
 * element self-defining.
 */
export class HTMLMapMetaElement extends HTMLElement {
  static get observedAttributes() {
    return ['name', 'content'];
  }
  get name() {
    return this.getAttribute('name');
  }
  set name(val) {
    if (['projection', 'extent', 'cs', 'zoom'].includes(val)) {
      this.setAttribute('name', val);
    }
  }
  get content() {
    return this.getAttribute('content');
  }
  set content(val) {
    // improve this
    if (
      this.name === 'cs' &&
      !['tcrs', 'tilematrix', 'pcrs', 'gcrs', 'map', 'tile'].includes(val)
    ) {
      return;
    }
    this.setAttribute('content', val);
  }

  attributeChangedCallback(name, oldValue, newValue) {
    switch (name) {
      case 'name': {
        if (oldValue !== newValue) {
          // handle side effects
        }
        break;
      }
      case 'content': {
        if (oldValue !== newValue) {
          // handle side effects
        }
        break;
      }
    }
  }
  constructor() {
    // Always call super first in constructor
    super();
  }
  connectedCallback() {}
  disconnectedCallback() {}
}
